import { createContext, useContext, useState, useEffect, type ReactNode } from 'react';
import { useParams } from 'react-router-dom';
import { doc, onSnapshot } from 'firebase/firestore';
import { db } from '@/services/firebase/config';
import type { Restaurant } from '@/types';
import { SubscriptionExpiredPage } from '@/pages/Public/SubscriptionExpiredPage';

import { getPeruNow } from '@/utils/dateUtils';

interface TenantContextType {
    tenant: Restaurant | null;
    isLoading: boolean;
    error: string | null;
}

const TenantContext = createContext<TenantContextType | undefined>(undefined);

export function TenantProvider({ children }: { children: ReactNode }) {
    // Note: This relies on the Route structure /:restaurantSlug/*
    const { restaurantSlug } = useParams<{ restaurantSlug: string }>();

    const [tenant, setTenant] = useState<Restaurant | null>(null);
    const [isLoading, setIsLoading] = useState(true);
    const [error, setError] = useState<string | null>(null);

    useEffect(() => {
        if (!restaurantSlug) {
            setIsLoading(false);
            setTenant(null);
            setError(null);
            return;
        }

        setIsLoading(true);
        setError(null);

        // For MVP SaaS, we treat the SLUG as the Firebase Document ID directly.
        const docRef = doc(db, 'restaurants', restaurantSlug);

        // Subscribe to real-time changes
        const unsubscribe = onSnapshot(docRef, (docSnap) => {
            if (docSnap.exists()) {
                const data = docSnap.data();
                const restaurantData = { id: docSnap.id, ...data } as Restaurant;

                // 1. Check if manually deactivated
                if (data.active === false) {
                    setTenant(null);
                    setError('ESTE RESTAURANTE ESTÁ INACTIVO. El servicio ha sido suspendido por el administrador.');
                    setIsLoading(false);
                    return;
                }

                // 2. Check for expiration
                let isExpired = false;
                const now = getPeruNow();

                if (data.subscriptionEndsAt) {
                    const endDate = data.subscriptionEndsAt.seconds ? new Date(data.subscriptionEndsAt.seconds * 1000) : new Date(data.subscriptionEndsAt);
                    if (now > endDate) isExpired = true;
                } else {
                    // Trial Logic (28 days)
                    const createdAt = data.createdAt.seconds ? new Date(data.createdAt.seconds * 1000) : new Date(data.createdAt);
                    const diffTime = now.getTime() - createdAt.getTime();
                    const diffDays = diffTime / (1000 * 3600 * 24);
                    if (diffDays > 28) isExpired = true;
                }

                if (isExpired) {
                    setTenant(null);
                    setError('LA SUSCRIPCIÓN HA VENCIDO. Para continuar usando el servicio debe renovar su plan.');
                } else {
                    setTenant(restaurantData);
                    setError(null);
                }
            } else {
                console.warn(`Tenant not found for slug: ${restaurantSlug}`);
                setError('Restaurante no encontrado');
                setTenant(null);
            }
            setIsLoading(false);
        }, (err) => {
            console.error("Error subscribing to tenant:", err);
            setError('Error de conexión al cargar restaurante');
            setIsLoading(false);
        });

        return () => unsubscribe();
    }, [restaurantSlug]);

    // ... (existing code)

    if (error !== null) {
        return <SubscriptionExpiredPage error={error} />;
    }

    return (
        <TenantContext.Provider value={{ tenant, isLoading, error }}>
            {children}
        </TenantContext.Provider>
    );
}

export function useTenant() {
    const context = useContext(TenantContext);
    if (context === undefined) {
        throw new Error('useTenant must be used within a TenantProvider');
    }
    return context;
}

import { useState, useRef, useEffect } from 'react';
import { Building2, ChevronDown, Check, MapPin } from 'lucide-react';
import { useBranch } from '@/app/providers/BranchProvider';

export function BranchSelector() {
    const { currentBranch, allBranches, isMultiBranch, switchBranch } = useBranch();
    const [isOpen, setIsOpen] = useState(false);
    const dropdownRef = useRef<HTMLDivElement>(null);

    // If not multi-branch or only one branch, don't render
    if (!isMultiBranch || allBranches.length <= 1) return null;

    // Close on click outside
    useEffect(() => {
        const handleClickOutside = (e: MouseEvent) => {
            if (dropdownRef.current && !dropdownRef.current.contains(e.target as Node)) {
                setIsOpen(false);
            }
        };
        if (isOpen) document.addEventListener('mousedown', handleClickOutside);
        return () => document.removeEventListener('mousedown', handleClickOutside);
    }, [isOpen]);

    return (
        <div ref={dropdownRef} style={{ position: 'relative' }}>
            <button
                onClick={() => setIsOpen(!isOpen)}
                style={{
                    display: 'flex',
                    alignItems: 'center',
                    gap: '0.5rem',
                    padding: '0.5rem 1rem',
                    background: 'var(--surface-color)',
                    border: '1px solid var(--divider-color)',
                    borderRadius: 'var(--radius-md)',
                    cursor: 'pointer',
                    color: 'var(--text-primary)',
                    fontSize: '0.9rem',
                    fontWeight: 600,
                    transition: 'all 0.2s',
                    boxShadow: isOpen ? '0 0 0 2px var(--primary-color)' : 'var(--shadow-sm)',
                }}
            >
                <Building2 size={16} color="var(--primary-color)" />
                <span style={{ maxWidth: '160px', overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
                    {currentBranch?.name || 'Seleccionar local'}
                </span>
                <ChevronDown
                    size={14}
                    style={{
                        transition: 'transform 0.2s',
                        transform: isOpen ? 'rotate(180deg)' : 'rotate(0)',
                        color: 'var(--text-secondary)',
                    }}
                />
            </button>

            {isOpen && (
                <div style={{
                    position: 'absolute',
                    top: 'calc(100% + 6px)',
                    right: 0,
                    minWidth: '240px',
                    background: 'var(--surface-color)',
                    border: '1px solid var(--divider-color)',
                    borderRadius: 'var(--radius-lg)',
                    boxShadow: '0 8px 24px rgba(0,0,0,0.12)',
                    zIndex: 100,
                    overflow: 'hidden',
                    animation: 'fadeInDropdown 0.15s ease-out',
                }}>
                    <div style={{
                        padding: '0.75rem 1rem 0.5rem',
                        fontSize: '0.75rem',
                        fontWeight: 700,
                        color: 'var(--text-secondary)',
                        textTransform: 'uppercase',
                        letterSpacing: '0.05em',
                        borderBottom: '1px solid var(--divider-color)',
                    }}>
                        Sucursales
                    </div>
                    {allBranches.map((branch) => {
                        const isActive = branch.id === currentBranch?.id;
                        return (
                            <button
                                key={branch.id}
                                onClick={() => {
                                    switchBranch(branch.id);
                                    setIsOpen(false);
                                }}
                                style={{
                                    display: 'flex',
                                    alignItems: 'center',
                                    gap: '0.75rem',
                                    width: '100%',
                                    padding: '0.75rem 1rem',
                                    border: 'none',
                                    background: isActive ? 'rgba(37, 99, 235, 0.06)' : 'transparent',
                                    cursor: 'pointer',
                                    color: 'var(--text-primary)',
                                    fontSize: '0.9rem',
                                    textAlign: 'left',
                                    transition: 'background 0.15s',
                                    borderBottom: '1px solid var(--divider-color)',
                                }}
                                onMouseEnter={(e) => {
                                    if (!isActive) (e.currentTarget as HTMLButtonElement).style.background = 'rgba(0,0,0,0.03)';
                                }}
                                onMouseLeave={(e) => {
                                    (e.currentTarget as HTMLButtonElement).style.background = isActive ? 'rgba(37, 99, 235, 0.06)' : 'transparent';
                                }}
                            >
                                <div style={{
                                    width: '32px',
                                    height: '32px',
                                    borderRadius: 'var(--radius-md)',
                                    background: isActive ? 'var(--primary-color)' : 'var(--background-color)',
                                    color: isActive ? 'white' : 'var(--text-secondary)',
                                    display: 'flex',
                                    alignItems: 'center',
                                    justifyContent: 'center',
                                    flexShrink: 0,
                                }}>
                                    <MapPin size={16} />
                                </div>
                                <div style={{ flex: 1, minWidth: 0 }}>
                                    <div style={{
                                        fontWeight: isActive ? 700 : 500,
                                        color: isActive ? 'var(--primary-color)' : 'var(--text-primary)',
                                        overflow: 'hidden',
                                        textOverflow: 'ellipsis',
                                        whiteSpace: 'nowrap',
                                    }}>
                                        {branch.name}
                                        {branch.isParent && (
                                            <span style={{ fontSize: '0.7rem', marginLeft: '0.5rem', color: 'var(--text-secondary)', fontWeight: 400 }}>
                                                (Principal)
                                            </span>
                                        )}
                                    </div>
                                    {branch.address && (
                                        <div style={{
                                            fontSize: '0.78rem',
                                            color: 'var(--text-secondary)',
                                            overflow: 'hidden',
                                            textOverflow: 'ellipsis',
                                            whiteSpace: 'nowrap',
                                        }}>
                                            {branch.address}
                                        </div>
                                    )}
                                </div>
                                {isActive && <Check size={16} color="var(--primary-color)" />}
                            </button>
                        );
                    })}
                </div>
            )}

            <style>{`
                @keyframes fadeInDropdown {
                    from { opacity: 0; transform: translateY(-4px); }
                    to { opacity: 1; transform: translateY(0); }
                }
            `}</style>
        </div>
    );
}

import { useState, useEffect } from 'react';
import { X, DollarSign, ShoppingBag, Clock, CreditCard, Smartphone, Banknote, User, AlertCircle, FileText } from 'lucide-react';
import { db } from '@/services/firebase/config';
import { collection, query, where, getDocs } from 'firebase/firestore';
import { parseISO, format } from 'date-fns';
import { es } from 'date-fns/locale';
import { Card, Badge, Skeleton } from '@/components/shared';
import type { Order } from '@/types';

interface DayRecord {
    date: string;
    totalSales: number;
    orderCount: number;
    salesByWaiter: Record<string, number>;
    salesByPaymentMethod: Record<string, number>;
    createdByName?: string;
    closureId?: string;
    closureStatus?: 'open' | 'closed';
}

interface DailyReportPreviewModalProps {
    restaurantId: string;
    record: DayRecord;
    onClose: () => void;
}

export function DailyReportPreviewModal({ restaurantId, record, onClose }: DailyReportPreviewModalProps) {
    const [orders, setOrders] = useState<Order[]>([]);
    const [isLoading, setIsLoading] = useState(true);
    const [error, setError] = useState<string | null>(null);

    useEffect(() => {
        const fetchOrders = async () => {
            setIsLoading(true);
            setError(null);
            try {
                // OPT B1: Server-side filter by dateStr + status to avoid downloading all orders
                const q = query(
                    collection(db, 'orders'),
                    where('restaurantId', '==', restaurantId),
                    where('status', '==', 'paid'),
                    where('dateStr', '==', record.date)
                );
                const snapshot = await getDocs(q);

                const paidOrders = snapshot.docs
                    .map(d => {
                        const data = d.data();
                        const createdAt = data.createdAt?.toDate ? data.createdAt.toDate() : new Date(data.createdAt);
                        return { id: d.id, ...data, createdAt } as Order;
                    })
                    .sort((a, b) => b.createdAt.getTime() - a.createdAt.getTime()); // Newer first

                setOrders(paidOrders);
            } catch (err) {
                console.error('Error fetching orders for preview:', err);
                setError('No se pudieron cargar los detalles del día. Por favor, reintente.');
            } finally {
                setIsLoading(false);
            }
        };

        fetchOrders();
    }, [restaurantId, record.date]);

    // Formatters & UI Helpers
    const formattedDate = format(parseISO(record.date), "EEEE, dd 'de' MMMM yyyy", { locale: es });
    const capitalizedDate = formattedDate.charAt(0).toUpperCase() + formattedDate.slice(1);

    const tkPromedio = record.orderCount > 0 ? record.totalSales / record.orderCount : 0;

    const getPaymentIcon = (method: string) => {
        switch (method.toLowerCase()) {
            case 'cash': case 'efectivo': return <Banknote size={16} />;
            case 'yape': case 'plin': return <Smartphone size={16} />;
            case 'card': case 'tarjeta': return <CreditCard size={16} />;
            default: return <DollarSign size={16} />;
        }
    };

    const getPaymentLabel = (method: string) => {
        const lower = method.toLowerCase();
        if (lower === 'cash') return 'Efectivo';
        if (lower === 'card') return 'Tarjeta';
        return method.charAt(0).toUpperCase() + method.slice(1);
    };

    return (
        <div style={{
            position: 'fixed', top: 0, left: 0, right: 0, bottom: 0,
            backgroundColor: 'rgba(15, 23, 42, 0.75)',
            backdropFilter: 'blur(8px)',
            display: 'flex', justifyContent: 'center', alignItems: 'center',
            zIndex: 1200, padding: '1rem',
            animation: 'fadeIn 0.2s ease-out'
        }}>
            <div style={{
                width: '100%', maxWidth: '900px',
                backgroundColor: 'var(--surface-color)',
                borderRadius: 'var(--radius-xl)',
                boxShadow: '0 25px 50px -12px rgba(0, 0, 0, 0.4)',
                display: 'flex', flexDirection: 'column',
                maxHeight: '90vh', overflow: 'hidden',
                animation: 'slideUp 0.3s cubic-bezier(0.16, 1, 0.3, 1)'
            }}>
                {/* Header */}
                <div style={{
                    padding: '1.5rem 2rem', borderBottom: '1px solid var(--divider-color)',
                    display: 'flex', justifyContent: 'space-between', alignItems: 'center',
                    background: 'linear-gradient(to right, #f8fafc, #ffffff)'
                }}>
                    <div>
                        <h2 style={{ margin: 0, display: 'flex', alignItems: 'center', gap: '0.75rem', fontSize: '1.5rem', color: 'var(--text-primary)' }}>
                            <FileText size={24} className="text-primary" />
                            Vista Previa del Día
                        </h2>
                        <p style={{ margin: '0.25rem 0 0 0', color: 'var(--text-secondary)', fontSize: '0.95rem', fontWeight: '500' }}>
                            {capitalizedDate}
                        </p>
                    </div>
                    <button onClick={onClose} style={{
                        background: 'var(--background-color)', border: '1px solid var(--divider-color)',
                        borderRadius: '50%', width: '36px', height: '36px',
                        display: 'flex', alignItems: 'center', justifyContent: 'center',
                        color: 'var(--text-secondary)', cursor: 'pointer', transition: 'all 0.2s'
                    }}
                        onMouseEnter={e => { e.currentTarget.style.backgroundColor = '#f1f5f9'; e.currentTarget.style.color = 'var(--text-primary)'; }}
                        onMouseLeave={e => { e.currentTarget.style.backgroundColor = 'var(--background-color)'; e.currentTarget.style.color = 'var(--text-secondary)'; }}>
                        <X size={20} />
                    </button>
                </div>

                {/* Body - Scrollable */}
                <div style={{ padding: '2rem', overflowY: 'auto', display: 'flex', flexDirection: 'column', gap: '2rem' }}>

                    {/* General Summary */}
                    <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(220px, 1fr))', gap: '1rem' }}>
                        <Card style={{ padding: '1.5rem', display: 'flex', alignItems: 'center', gap: '1rem', borderTop: '3px solid var(--primary-color)' }}>
                            <div style={{
                                width: '48px', height: '48px', borderRadius: '12px',
                                background: 'rgba(14, 165, 233, 0.1)', color: 'var(--primary-color)',
                                display: 'flex', alignItems: 'center', justifyContent: 'center'
