                                                <th style={{ padding: '0.85rem 1rem', color: 'var(--text-secondary)', fontWeight: '700' }}>Detalle</th>
                                                <th style={{ padding: '0.85rem 1rem', color: 'var(--text-secondary)', fontWeight: '700' }}>Atendido por</th>
                                                <th style={{ padding: '0.85rem 1rem', color: 'var(--text-secondary)', fontWeight: '700' }}>Método(s)</th>
                                                <th style={{ padding: '0.85rem 1rem', color: 'var(--text-secondary)', fontWeight: '700', textAlign: 'right' }}>Total</th>
                                            </tr>
                                        </thead>
                                        <tbody>
                                            {orders.map((o) => (
                                                <tr key={o.id} style={{ borderBottom: '1px solid var(--divider-color)', transition: 'background 0.2s' }}
                                                    onMouseEnter={e => e.currentTarget.style.backgroundColor = 'var(--background-color)'}
                                                    onMouseLeave={e => e.currentTarget.style.backgroundColor = 'transparent'}
                                                >
                                                    <td style={{ padding: '1rem', fontWeight: '500' }}>
                                                        {format(o.createdAt, 'hh:mm a')}
                                                    </td>
                                                    <td style={{ padding: '1rem' }}>
                                                        <div style={{ fontWeight: '600', color: 'var(--text-primary)' }}>
                                                            {o.orderType === 'takeout' ? (
                                                                <span style={{ display: 'inline-flex', alignItems: 'center', gap: '4px' }}><ShoppingBag size={14} /> Para Llevar</span>
                                                            ) : `Mesa ${o.tableNumber}`}
                                                        </div>
                                                        {(o.customerName || (o as any).clientName) && (
                                                            <div style={{ fontSize: '0.8rem', color: 'var(--text-secondary)', marginTop: '2px' }}>
                                                                Cliente: {o.customerName || (o as any).clientName}
                                                            </div>
                                                        )}
                                                    </td>
                                                    <td style={{ padding: '1rem', color: 'var(--text-secondary)', fontWeight: '500' }}>
                                                        {o.userName || 'Desconocido'}
                                                    </td>
                                                    <td style={{ padding: '1rem' }}>
                                                        <div style={{ display: 'flex', flexWrap: 'wrap', gap: '4px' }}>
                                                            {o.payments && o.payments.length > 0 ? (
                                                                o.payments.map((p, idx) => (
                                                                    <Badge key={idx} variant="neutral" style={{ fontSize: '0.7rem', padding: '0.15rem 0.4rem' }}>
                                                                        {getPaymentLabel(p.method)}
                                                                    </Badge>
                                                                ))
                                                            ) : o.paymentMethod ? (
                                                                <Badge variant="neutral" style={{ fontSize: '0.7rem', padding: '0.15rem 0.4rem' }}>
                                                                    {getPaymentLabel(o.paymentMethod)}
                                                                </Badge>
                                                            ) : (
                                                                <span style={{ color: 'var(--text-secondary)', fontSize: '0.85rem' }}>-</span>
                                                            )}
                                                        </div>
                                                    </td>
                                                    <td style={{ padding: '1rem', textAlign: 'right', fontWeight: '800', color: 'var(--text-primary)' }}>
                                                        S/ {o.total.toFixed(2)}
                                                    </td>
                                                </tr>
                                            ))}
                                        </tbody>
                                    </table>
                                </div>
                            </div>
                        )}
                    </div>
                </div>
            </div>
        </div>
    );
}

import { useState } from 'react';
import type { ReactNode } from 'react';
import { PaymentModal } from '@/components/features/PaymentModal';
import { useOrders } from '@/hooks/useOrders';
import { useAuth } from '@/hooks/useAuth';
import { useTenant } from '@/app/providers/TenantProvider';
import type { Order, OrderStatus, OrderPayment } from '@/types';
import { formatDistanceToNow } from 'date-fns';
import { es } from 'date-fns/locale';
import { Clock, CheckCircle2, ChefHat, Truck, Banknote, Pencil, Trash2, Printer, MessageSquare } from 'lucide-react';
import { printerService } from '@/services/printer/PrinterService';

interface OrderCardProps {
    order: Order;
    actions?: ReactNode; // Kept for backwards compatibility or extra actions, but mainly we build internal actions now
    onEdit?: () => void;
    onDelete?: () => void;
}

export function OrderCard({ order, onEdit, onDelete }: OrderCardProps) {
    const { user } = useAuth();
    const { tenant } = useTenant();
    const { updateOrderStatus, payOrder } = useOrders();
    const [showPaymentModal, setShowPaymentModal] = useState(false);

    const handleStatusChange = (newStatus: OrderStatus) => {
        updateOrderStatus(order.id, newStatus);
    };

    const handlePayment = async (payments: OrderPayment[], shouldPrintReceipt: boolean, discount?: { type: 'percentage' | 'fixed'; value: number; amount: number }) => {
        try {
            await payOrder(order.id, payments, discount);
            if (shouldPrintReceipt && printerService.isConnected) {
                try {
                    // Update the order reference for printing if discount was applied
                    const printOrder = { ...order, payments, status: 'paid' as OrderStatus };
                    if (discount && discount.amount > 0) {
                        printOrder.subtotal = order.total;
                        printOrder.discount = discount;
                        printOrder.total = parseFloat((order.total - discount.amount).toFixed(2));
                    }
                    await printerService.printReceipt(printOrder, tenant?.name || 'Restaurante');
                } catch (printError) {
                    console.error('Error printing receipt:', printError);
                    // Don't block payment flow if printing fails
                }
            }
            setShowPaymentModal(false);
        } catch (error) {
            console.error('Payment failed', error);
            alert('Error al registrar pago');
        }
    };

    const getStatusColor = (status: OrderStatus) => {
        switch (status) {
            case 'pending': return 'var(--warning-color)';
            case 'in_preparation': return 'var(--info-color)';
            case 'ready': return 'var(--success-color)';
            case 'delivered': return 'var(--text-secondary)';
            default: return 'var(--text-secondary)';
        }
    };

    const getStatusLabel = (status: OrderStatus) => {
        switch (status) {
            case 'pending': return 'Pendiente';
            case 'in_preparation': return 'En Cocina';
            case 'ready': return 'Listo';
            case 'delivered': return 'Entregado';
            case 'paid': return 'Cobrado';
            case 'cancelled': return 'Cancelado';
            default: return status;
        }
    };

    const MainActionButton = () => {
        const usarPantallaCocina = tenant?.config?.usarPantallaCocina ?? false;

        const btnEntregar = (
            <button
                onClick={() => handleStatusChange('delivered')}
                style={{
                    flex: 1,
                    backgroundColor: 'var(--text-primary)',
                    color: 'white',
                    border: 'none',
                    borderRadius: 'var(--radius-md)',
                    padding: '0.85rem',
                    fontWeight: '700',
                    cursor: 'pointer',
                    display: 'flex', alignItems: 'center', justifyContent: 'center', gap: '0.6rem'
                }}
            >
                <Truck size={18} /> Entregar
            </button>
        );

        switch (order.status) {
            case 'pending':
                if (!usarPantallaCocina) return btnEntregar;
                return (
                    <button
                        onClick={() => handleStatusChange('in_preparation')}
                        style={{
                            flex: 1,
                            backgroundColor: 'var(--info-color)',
                            color: 'white',
                            border: 'none',
                            borderRadius: 'var(--radius-md)',
                            padding: '0.85rem',
                            fontWeight: '700',
                            cursor: 'pointer',
                            display: 'flex', alignItems: 'center', justifyContent: 'center', gap: '0.6rem',
                            transition: 'all 0.2s',
                            boxShadow: '0 4px 10px rgba(113, 146, 190, 0.2)'
                        }}
                    >
                        <ChefHat size={18} /> Preparar
                    </button>
                );
            case 'in_preparation':
                if (!usarPantallaCocina) return btnEntregar;
                return (
                    <button
                        onClick={() => handleStatusChange('ready')}
                        style={{
                            flex: 1,
                            backgroundColor: 'var(--success-color)',
                            color: 'white',
                            border: 'none',
                            borderRadius: 'var(--radius-md)',
                            padding: '0.85rem',
                            fontWeight: '700',
                            cursor: 'pointer',
                            display: 'flex', alignItems: 'center', justifyContent: 'center', gap: '0.6rem',
                            boxShadow: '0 4px 10px rgba(127, 176, 105, 0.2)'
                        }}
                    >
                        <CheckCircle2 size={18} /> Marcar Listo
                    </button>
                );
            case 'ready':
                return btnEntregar;
            case 'delivered':
                return (
                    <button
                        onClick={() => setShowPaymentModal(true)}
                        style={{
                            flex: 1,
                            backgroundColor: 'var(--primary-color)',
                            color: 'white',
                            border: 'none',
                            borderRadius: 'var(--radius-md)',
                            padding: '0.85rem',
                            fontWeight: '700',
                            cursor: 'pointer',
                            display: 'flex', alignItems: 'center', justifyContent: 'center', gap: '0.6rem',
                            boxShadow: '0 4px 10px rgba(142, 115, 91, 0.2)'
                        }}
                    >
                        <Banknote size={18} /> Cobrar Cuenta
                    </button>
                );
            default:
                return null;
        }
    };

    return (
