import { useState, useEffect } from 'react';
import { X, Smartphone, Banknote, CreditCard, Printer, Trash2, Plus, Percent, DollarSign, Tag } from 'lucide-react';
import type { Order, PaymentMethod, OrderPayment, OrderDiscount } from '@/types';
import { printerService } from '@/services/printer/PrinterService';

interface PaymentModalProps {
    order: Order;
    onClose: () => void;
    onConfirmPayment: (payments: OrderPayment[], printReceipt: boolean, discount?: OrderDiscount) => void;
}

export function PaymentModal({ order, onClose, onConfirmPayment }: PaymentModalProps) {
    const [payments, setPayments] = useState<OrderPayment[]>([]);
    const [currentMethod, setCurrentMethod] = useState<PaymentMethod | null>(null);
    const [inputAmount, setInputAmount] = useState<string>('');

    const printerConnected = printerService.isConnected;
    const [printReceipt, setPrintReceipt] = useState(printerConnected);

    // Discount state
    const [showDiscount, setShowDiscount] = useState(false);
    const [discountType, setDiscountType] = useState<'percentage' | 'fixed'>('percentage');
    const [discountValue, setDiscountValue] = useState<string>('');

    // Calculate discount amount
    const rawDiscountValue = parseFloat(discountValue) || 0;
    const discountAmount = discountType === 'percentage'
        ? Math.min(order.total * rawDiscountValue / 100, order.total)
        : Math.min(rawDiscountValue, order.total);
    const finalTotal = Math.max(0, order.total - discountAmount);

    const totalPaid = payments.reduce((sum, p) => sum + p.amount, 0);
    const remaining = Math.max(0, finalTotal - totalPaid);
    const isFullyPaid = remaining <= 0.01; // Avoid float precision issues

    // Sync input amount with remaining when remaining changes, if not fully paid
    useEffect(() => {
        if (!isFullyPaid) {
            setInputAmount(remaining.toFixed(2));
        } else {
            setInputAmount('');
            setCurrentMethod(null);
        }
    }, [remaining, isFullyPaid]);

    // Reset payments when discount changes
    useEffect(() => {
        setPayments([]);
    }, [discountAmount]);

    const handleAddPayment = () => {
        if (!currentMethod) return;
        const amount = parseFloat(inputAmount);
        if (isNaN(amount) || amount <= 0) {
            alert('Ingrese un monto válido');
            return;
        }
        if (amount > remaining + 0.01) {
            alert('El monto no puede ser mayor al saldo restante');
            return;
        }

        setPayments(prev => [...prev, { method: currentMethod, amount }]);
        setCurrentMethod(null);
    };

    const handleRemovePayment = (index: number) => {
        setPayments(prev => prev.filter((_, i) => i !== index));
    };

    const handleConfirm = () => {
        if (!isFullyPaid) return;
        const discount: OrderDiscount | undefined = discountAmount > 0
            ? { type: discountType, value: rawDiscountValue, amount: parseFloat(discountAmount.toFixed(2)) }
            : undefined;
        onConfirmPayment(payments, printReceipt, discount);
    };

    const methods = [
        {
            id: 'cash' as PaymentMethod,
            title: 'Efectivo',
            description: 'Pago en efectivo',
            icon: <Banknote size={22} />,
            color: 'var(--primary-color)',
            bg: 'var(--divider-color)'
        },
        {
            id: 'yape' as PaymentMethod,
            title: 'Yape / Plin',
            description: 'Pago digital instantáneo',
            icon: <Smartphone size={22} />,
            color: '#6366f1',
            bg: '#F5F5FF'
        },
        {
            id: 'card' as PaymentMethod,
            title: 'Tarjeta',
            description: 'Débito o crédito',
            icon: <CreditCard size={22} />,
            color: 'var(--text-secondary)',
            bg: 'var(--divider-color)'
        }
    ];

    const getMethodTitle = (id: PaymentMethod) => methods.find(m => m.id === id)?.title || id;

    return (
        <div style={{
            position: 'fixed', top: 0, left: 0, right: 0, bottom: 0,
            backgroundColor: 'rgba(255, 255, 255, 0.7)',
            backdropFilter: 'blur(12px)',
            display: 'flex', justifyContent: 'center', alignItems: 'center',
            zIndex: 1100,
            padding: '1rem'
        }}>
            <div style={{
                width: '100%',
                maxWidth: '450px',
                backgroundColor: 'var(--surface-color)',
                borderRadius: 'var(--radius-lg)',
                overflow: 'hidden',
                boxShadow: 'var(--shadow-lg)',
                display: 'flex',
                flexDirection: 'column',
                maxHeight: '90vh',
                border: '1px solid var(--border-color)'
            }}>
                {/* Header */}
                <div style={{
                    padding: '2.5rem 2rem 1.5rem',
                    position: 'relative',
                    textAlign: 'center',
                    borderBottom: '1px solid var(--divider-color)'
                }}>
                    <button
                        onClick={onClose}
                        style={{
                            position: 'absolute', top: '1.25rem', right: '1.25rem',
                            background: 'var(--divider-color)', border: 'none',
                            borderRadius: '50%', width: '32px', height: '32px',
                            display: 'flex', alignItems: 'center', justifyContent: 'center',
                            color: 'var(--text-secondary)', cursor: 'pointer'
                        }}
                    >
                        <X size={18} />
                    </button>

                    <p style={{
                        color: 'var(--text-secondary)',
                        fontSize: '0.75rem',
                        fontWeight: '700',
                        letterSpacing: '0.1em',
                        marginBottom: '0.5rem',
                        textTransform: 'uppercase'
                    }}>Total de la Cuenta</p>

                    {/* Show subtotal crossed out if there's a discount */}
                    {discountAmount > 0 && (
                        <div style={{
                            fontSize: '1.1rem',
                            fontWeight: '600',
                            color: 'var(--text-secondary)',
                            textDecoration: 'line-through',
                            marginBottom: '0.25rem',
                            opacity: 0.6
                        }}>
                            S/ {order.total.toFixed(2)}
                        </div>
                    )}

                    <div style={{
                        fontSize: '2.5rem',
                        fontWeight: '900',
                        lineHeight: 1,
                        marginBottom: '0.5rem',
                        color: discountAmount > 0 ? 'var(--success-color)' : 'var(--text-primary)',
                        letterSpacing: '-0.02em',
                        transition: 'color 0.3s'
                    }}>
                        <span style={{ fontSize: '1.25rem', verticalAlign: 'super', marginRight: '4px' }}>S/</span>
                        {finalTotal.toFixed(2)}
                    </div>

                    {discountAmount > 0 && (
                        <div style={{
                            display: 'inline-flex',
                            alignItems: 'center',
                            gap: '0.35rem',
                            background: 'rgba(76, 175, 80, 0.1)',
                            color: 'var(--success-color)',
                            padding: '3px 10px',
                            borderRadius: 'var(--radius-full)',
                            fontSize: '0.75rem',
                            fontWeight: '700',
                            marginBottom: '0.5rem'
                        }}>
                            <Tag size={12} />
                            Descuento: −S/ {discountAmount.toFixed(2)}
                            {discountType === 'percentage' && ` (${rawDiscountValue}%)`}
                        </div>
                    )}

                    <div style={{
                        display: 'flex',
                        alignItems: 'center',
                        justifyContent: 'center',
                        gap: '1rem',
                        fontSize: '0.8rem',
                        color: 'var(--text-secondary)',
                        fontWeight: '600'
                    }}>
                        <div style={{
                            display: 'flex',
                            alignItems: 'center',
                            gap: '0.5rem',
                            background: 'var(--background-color)',
                            padding: '4px 12px',
                            borderRadius: 'var(--radius-full)',
                            border: '1px solid var(--border-color)'
                        }}>
                            <span style={{ width: '8px', height: '8px', borderRadius: '50%', backgroundColor: 'var(--success-color)' }}></span>
                            {order.orderType === 'takeout' ? 'Para Llevar' : `Mesa ${order.tableNumber}`}
                        </div>
                    </div>
                </div>

                {/* Body */}
                <div style={{ padding: '1.5rem', overflowY: 'auto', display: 'flex', flexDirection: 'column', gap: '1.5rem' }}>

                    {/* === Discount Section === */}
                    <div>
                        <button
                            onClick={() => setShowDiscount(!showDiscount)}
                            style={{
                                display: 'flex',
                                alignItems: 'center',
                                gap: '0.5rem',
                                width: '100%',
                                padding: '0.75rem 1rem',
                                borderRadius: 'var(--radius-md)',
                                border: `1.5px dashed ${showDiscount || discountAmount > 0 ? 'var(--success-color)' : 'var(--border-color)'}`,
                                backgroundColor: discountAmount > 0 ? 'rgba(76, 175, 80, 0.06)' : 'var(--background-color)',
                                color: discountAmount > 0 ? 'var(--success-color)' : 'var(--text-secondary)',
                                fontWeight: '700',
                                fontSize: '0.85rem',
                                cursor: 'pointer',
                                transition: 'all 0.2s'
                            }}
                        >
                            <Tag size={16} />
                            {discountAmount > 0
                                ? `Descuento aplicado: −S/ ${discountAmount.toFixed(2)}`
                                : 'Aplicar Descuento'}
                            <span style={{ marginLeft: 'auto', fontSize: '0.75rem', opacity: 0.7 }}>
                                {showDiscount ? '▲' : '▼'}
                            </span>
                        </button>

                        {showDiscount && (
                            <div style={{
                                marginTop: '0.75rem',
                                padding: '1rem',
                                borderRadius: 'var(--radius-md)',
                                backgroundColor: 'var(--background-color)',
                                border: '1px solid var(--border-color)',
                                display: 'flex',
                                flexDirection: 'column',
                                gap: '0.75rem',
                                animation: 'fadeIn 0.2s ease'
                            }}>
                                {/* Type toggle */}
                                <div style={{
                                    display: 'grid',
                                    gridTemplateColumns: '1fr 1fr',
                                    gap: '0.5rem',
                                    padding: '4px',
                                    backgroundColor: 'var(--surface-color)',
                                    borderRadius: 'var(--radius-md)',
                                    border: '1px solid var(--border-color)'
                                }}>
                                    {([
                                        { type: 'percentage' as const, icon: <Percent size={14} />, label: 'Porcentaje (%)' },
                                        { type: 'fixed' as const, icon: <DollarSign size={14} />, label: 'Monto Fijo (S/)' }
                                    ]).map(opt => {
                                        const isActive = discountType === opt.type;
                                        return (
                                            <button
                                                key={opt.type}
                                                onClick={() => { setDiscountType(opt.type); setDiscountValue(''); }}
                                                style={{
                                                    display: 'flex',
                                                    alignItems: 'center',
                                                    justifyContent: 'center',
                                                    gap: '0.4rem',
                                                    padding: '0.5rem',
                                                    borderRadius: '6px',
                                                    border: 'none',
                                                    backgroundColor: isActive ? 'var(--primary-color)' : 'transparent',
                                                    color: isActive ? 'white' : 'var(--text-secondary)',
                                                    fontWeight: '700',
                                                    fontSize: '0.78rem',
                                                    cursor: 'pointer',
                                                    transition: 'all 0.2s'
                                                }}
                                            >
                                                {opt.icon}
                                                {opt.label}
                                            </button>
                                        );
                                    })}
                                </div>

                                {/* Value input */}
                                <div style={{ position: 'relative' }}>
                                    <span style={{
                                        position: 'absolute', left: '1rem', top: '50%', transform: 'translateY(-50%)',
                                        color: 'var(--text-secondary)', fontWeight: 'bold', fontSize: '0.9rem'
                                    }}>
                                        {discountType === 'percentage' ? '%' : 'S/'}
                                    </span>
                                    <input
                                        type="number"
                                        placeholder={discountType === 'percentage' ? 'Ej: 10' : 'Ej: 5.00'}
                                        value={discountValue}
                                        onChange={(e) => {
                                            const val = e.target.value;
                                            if (discountType === 'percentage') {
                                                const num = parseFloat(val);
                                                if (val === '' || (num >= 0 && num <= 100)) setDiscountValue(val);
                                            } else {
                                                const num = parseFloat(val);
                                                if (val === '' || (num >= 0 && num <= order.total)) setDiscountValue(val);
                                            }
                                        }}
                                        min="0"
                                        max={discountType === 'percentage' ? '100' : String(order.total)}
                                        step={discountType === 'percentage' ? '1' : '0.50'}
                                        style={{
                                            width: '100%',
                                            padding: '0.85rem 1rem 0.85rem 2.5rem',
                                            borderRadius: 'var(--radius-md)',
                                            border: '1.5px solid var(--border-color)',
                                            backgroundColor: 'var(--surface-color)',
                                            color: 'var(--text-primary)',
                                            fontSize: '1.1rem',
                                            fontWeight: '700'
                                        }}
                                    />
                                </div>

                                {/* Quick percentage buttons */}
                                {discountType === 'percentage' && (
                                    <div style={{ display: 'flex', gap: '0.5rem', flexWrap: 'wrap' }}>
                                        {[5, 10, 15, 20, 50].map(pct => (
                                            <button
                                                key={pct}
                                                onClick={() => setDiscountValue(String(pct))}
                                                style={{
                                                    flex: 1,
                                                    minWidth: '50px',
                                                    padding: '0.5rem',
                                                    borderRadius: 'var(--radius-md)',
                                                    border: `1.5px solid ${rawDiscountValue === pct ? 'var(--primary-color)' : 'var(--border-color)'}`,
                                                    backgroundColor: rawDiscountValue === pct ? 'rgba(69, 123, 157, 0.08)' : 'var(--surface-color)',
                                                    color: rawDiscountValue === pct ? 'var(--primary-color)' : 'var(--text-secondary)',
                                                    fontWeight: '700',
                                                    fontSize: '0.8rem',
                                                    cursor: 'pointer',
                                                    transition: 'all 0.15s'
                                                }}
                                            >
                                                {pct}%
                                            </button>
                                        ))}
                                    </div>
                                )}

                                {/* Discount result preview */}
                                {discountAmount > 0 && (
                                    <div style={{
                                        display: 'flex',
                                        justifyContent: 'space-between',
                                        alignItems: 'center',
                                        padding: '0.6rem 0.75rem',
                                        borderRadius: 'var(--radius-md)',
                                        backgroundColor: 'rgba(76, 175, 80, 0.08)',
                                        border: '1px solid rgba(76, 175, 80, 0.2)'
                                    }}>
                                        <span style={{ fontSize: '0.8rem', color: 'var(--text-secondary)', fontWeight: '600' }}>
                                            Ahorro del cliente
                                        </span>
                                        <span style={{ fontSize: '1rem', fontWeight: '800', color: 'var(--success-color)' }}>
                                            −S/ {discountAmount.toFixed(2)}
                                        </span>
                                    </div>
                                )}

                                {/* Remove discount */}
                                {discountAmount > 0 && (
                                    <button
                                        onClick={() => { setDiscountValue(''); setShowDiscount(false); }}
                                        style={{
                                            display: 'flex', alignItems: 'center', justifyContent: 'center', gap: '0.4rem',
                                            padding: '0.5rem',
                                            borderRadius: 'var(--radius-md)',
                                            border: 'none',
                                            backgroundColor: 'rgba(239, 68, 68, 0.08)',
                                            color: 'var(--danger-color)',
                                            fontWeight: '600',
                                            fontSize: '0.8rem',
                                            cursor: 'pointer'
                                        }}
                                    >
                                        <Trash2 size={14} />
                                        Quitar descuento
                                    </button>
                                )}
                            </div>
                        )}
                    </div>

                    {/* Resumen de pago */}
                    <div style={{
                        display: 'flex',
                        justifyContent: 'space-between',
                        padding: '1rem',
                        backgroundColor: isFullyPaid ? 'rgba(76, 175, 80, 0.1)' : 'var(--background-color)',
                        borderRadius: 'var(--radius-md)',
                        border: `1px solid ${isFullyPaid ? 'var(--success-color)' : 'var(--border-color)'}`
                    }}>
                        <div style={{ display: 'flex', flexDirection: 'column' }}>
                            <span style={{ fontSize: '0.8rem', color: 'var(--text-secondary)', fontWeight: '600' }}>Pagado</span>
                            <span style={{ fontSize: '1.2rem', fontWeight: '800', color: 'var(--success-color)' }}>S/ {totalPaid.toFixed(2)}</span>
                        </div>
                        <div style={{ width: '1px', backgroundColor: 'var(--divider-color)', alignSelf: 'stretch' }}></div>
                        <div style={{ display: 'flex', flexDirection: 'column', textAlign: 'right' }}>
                            <span style={{ fontSize: '0.8rem', color: 'var(--text-secondary)', fontWeight: '600' }}>Saldo Restante</span>
                            <span style={{ fontSize: '1.2rem', fontWeight: '800', color: isFullyPaid ? 'var(--text-secondary)' : 'var(--danger-color)' }}>
                                S/ {remaining.toFixed(2)}
                            </span>
                        </div>
                    </div>

                    {/* Lista de pagos agregados */}
                    {payments.length > 0 && (
                        <div>
                            <p style={{ fontSize: '0.75rem', fontWeight: '800', color: 'var(--text-secondary)', marginBottom: '0.75rem', textTransform: 'uppercase', letterSpacing: '0.1em' }}>
                                Pagos Recibidos
                            </p>
                            <div style={{ display: 'flex', flexDirection: 'column', gap: '0.5rem' }}>
                                {payments.map((p, idx) => (
                                    <div key={idx} style={{
                                        display: 'flex', justifyContent: 'space-between', alignItems: 'center',
                                        padding: '0.75rem 1rem',
                                        backgroundColor: 'var(--surface-color)',
                                        border: '1px solid var(--border-color)',
                                        borderRadius: 'var(--radius-md)'
                                    }}>
                                        <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
                                            <span style={{ fontWeight: '700', color: 'var(--text-primary)' }}>{getMethodTitle(p.method)}</span>
                                        </div>
                                        <div style={{ display: 'flex', alignItems: 'center', gap: '1rem' }}>
                                            <span style={{ fontWeight: '800', color: 'var(--text-primary)' }}>S/ {p.amount.toFixed(2)}</span>
                                            <button
                                                onClick={() => handleRemovePayment(idx)}
                                                style={{
                                                    background: 'transparent', border: 'none', color: 'var(--danger-color)',
                                                    cursor: 'pointer', padding: '4px', display: 'flex', alignItems: 'center'
                                                }}
                                            >
                                                <Trash2 size={16} />
                                            </button>
                                        </div>
                                    </div>
                                ))}
                            </div>
                        </div>
                    )}

                    {/* Agregar nuevo pago (solo si hay saldo) */}
                    {!isFullyPaid && (
                        <div>
                            <p style={{ fontSize: '0.75rem', fontWeight: '800', color: 'var(--text-secondary)', marginBottom: '0.75rem', textTransform: 'uppercase', letterSpacing: '0.1em' }}>
                                Agregar Pago
                            </p>
                            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(3, 1fr)', gap: '0.5rem', marginBottom: '1rem' }}>
                                {methods.map((m) => {
                                    const isSelected = currentMethod === m.id;
                                    return (
                                        <div
                                            key={m.id}
                                            onClick={() => setCurrentMethod(m.id)}
                                            style={{
                                                border: `2px solid ${isSelected ? m.color : 'var(--border-color)'}`,
                                                borderRadius: 'var(--radius-md)',
                                                padding: '0.75rem 0.5rem',
                                                display: 'flex',
                                                flexDirection: 'column',
                                                alignItems: 'center',
                                                gap: '0.5rem',
                                                cursor: 'pointer',
                                                backgroundColor: isSelected ? `${m.color}08` : 'var(--surface-color)',
                                                transition: 'all 0.2s',
                                                textAlign: 'center'
                                            }}
                                        >
                                            <div style={{ color: isSelected ? m.color : 'var(--text-secondary)' }}>
                                                {m.icon}
                                            </div>
                                            <div style={{ fontWeight: '700', fontSize: '0.8rem', color: isSelected ? 'var(--text-primary)' : 'var(--text-secondary)' }}>
                                                {m.title}
                                            </div>
                                        </div>
                                    );
                                })}
                            </div>

                            {currentMethod && (
                                <div style={{ display: 'flex', gap: '0.5rem' }}>
                                    <div style={{ flex: 1, position: 'relative' }}>
                                        <span style={{ position: 'absolute', left: '1rem', top: '50%', transform: 'translateY(-50%)', color: 'var(--text-secondary)', fontWeight: 'bold' }}>S/</span>
                                        <input
                                            type="number"
                                            value={inputAmount}
                                            onChange={(e) => setInputAmount(e.target.value)}
                                            style={{
                                                width: '100%',
                                                padding: '0.85rem 1rem 0.85rem 2.5rem',
                                                borderRadius: 'var(--radius-md)',
                                                border: '1px solid var(--border-color)',
                                                backgroundColor: 'var(--background-color)',
                                                color: 'var(--text-primary)',
                                                fontSize: '1rem',
                                                fontWeight: '700'
                                            }}
                                        />
                                    </div>
                                    <button
                                        onClick={handleAddPayment}
                                        style={{
                                            padding: '0 1rem',
                                            backgroundColor: 'var(--primary-color)',
                                            color: 'white',
                                            border: 'none',
                                            borderRadius: 'var(--radius-md)',
                                            fontWeight: '700',
                                            cursor: 'pointer',
                                            display: 'flex',
                                            alignItems: 'center',
                                            gap: '0.5rem'
                                        }}
                                    >
                                        <Plus size={18} /> Agregar
                                    </button>
                                </div>
                            )}
                        </div>
                    )}
                </div>

                {/* Footer */}
                <div style={{
                    padding: '1.5rem',
                    borderTop: '1px solid var(--divider-color)',
                    display: 'flex',
                    flexDirection: 'column',
                    gap: '1rem',
                    backgroundColor: 'var(--surface-color)',
                    marginTop: 'auto'
                }}>
                    {/* Print Receipt Checkbox */}
                    <label
                        style={{
                            display: 'flex', alignItems: 'center', gap: '0.75rem',
                            padding: '0.85rem 1rem', borderRadius: 'var(--radius-md)',
                            border: `1px solid ${printerConnected ? 'var(--border-color)' : 'var(--divider-color)'}`,
                            backgroundColor: printReceipt ? 'rgba(69, 123, 157, 0.06)' : 'var(--background-color)',
                            cursor: printerConnected ? 'pointer' : 'default',
                            opacity: printerConnected ? 1 : 0.5,
                            transition: 'all 0.2s', userSelect: 'none'
                        }}
                    >
                        <div style={{
                            width: '20px', height: '20px', borderRadius: '4px',
                            border: `2px solid ${printReceipt ? 'var(--primary-color)' : 'var(--text-secondary)'}`,
                            backgroundColor: printReceipt ? 'var(--primary-color)' : 'transparent',
                            display: 'flex', alignItems: 'center', justifyContent: 'center',
                            transition: 'all 0.2s', flexShrink: 0
                        }}>
                            {printReceipt && (
                                <svg width="12" height="12" viewBox="0 0 12 12" fill="none">
                                    <path d="M2 6L5 9L10 3" stroke="white" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" />
                                </svg>
                            )}
                        </div>
                        <input
                            type="checkbox"
                            checked={printReceipt}
                            disabled={!printerConnected}
                            onChange={(e) => setPrintReceipt(e.target.checked)}
                            style={{ display: 'none' }}
                        />
                        <div style={{ flex: 1, minWidth: 0 }}>
                            <div style={{ fontWeight: '700', fontSize: '0.9rem', color: 'var(--text-primary)', display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
                                <Printer size={16} color="var(--primary-color)" />
                                Imprimir boleta
                            </div>
                            {!printerConnected && (
                                <div style={{ fontSize: '0.75rem', color: 'var(--text-secondary)', fontWeight: '500', marginTop: '2px' }}>
                                    Impresora no conectada
                                </div>
                            )}
                        </div>
                    </label>

                    <button
                        disabled={!isFullyPaid}
                        onClick={handleConfirm}
                        style={{
                            width: '100%',
                            padding: '1.25rem',
                            borderRadius: 'var(--radius-md)',
                            border: 'none',
                            background: isFullyPaid ? 'var(--primary-color)' : 'var(--divider-color)',
                            color: isFullyPaid ? 'white' : 'var(--text-secondary)',
                            fontWeight: '800',
                            fontSize: '1rem',
                            cursor: isFullyPaid ? 'pointer' : 'not-allowed',
                            boxShadow: isFullyPaid ? '0 8px 25px rgba(69, 123, 157, 0.3)' : 'none',
                            transition: 'all 0.3s'
                        }}
                    >
                        Confirmar y Finalizar
                    </button>
                    <button
                        onClick={onClose}
                        style={{
                            width: '100%',
                            padding: '0.5rem',
                            borderRadius: 'var(--radius-md)',
                            border: 'none',
                            backgroundColor: 'transparent',
                            color: 'var(--text-secondary)',
                            fontWeight: '600',
                            fontSize: '0.9rem',
                            cursor: 'pointer'
                        }}
                    >
                        Volver atrás
                    </button>
                </div>
            </div>
        </div>
    );
}

import { useState, useEffect } from 'react';
import { Bluetooth, Usb, Printer, Unlink, CheckCircle2, AlertCircle, ToggleLeft, ToggleRight, Smartphone, Wifi, Globe } from 'lucide-react';
import { Button } from '@/components/shared';
import { printerService } from '@/services/printer/PrinterService';

export function PrinterTab() {
    const [isConnected, setIsConnected] = useState(printerService.isConnected);
    const [deviceName, setDeviceName] = useState(printerService.connectedDeviceName);
    const [autoPrint, setAutoPrint] = useState(printerService.autoPrint);
    const [isLoading, setIsLoading] = useState(false);
    const [error, setError] = useState<string | null>(null);
    const [ipInput, setIpInput] = useState(localStorage.getItem('printer_ip') || '');

    // Sync connection state periodically (catches BLE disconnect, etc.)
    useEffect(() => {
        const interval = setInterval(() => {
            const currentConnected = printerService.isConnected;
            const currentName = printerService.connectedDeviceName;
            if (currentConnected !== isConnected) setIsConnected(currentConnected);
            if (currentName !== deviceName) setDeviceName(currentName);
        }, 2000);
        return () => clearInterval(interval);
    }, [isConnected, deviceName]);

    const handleConnectBluetooth = async () => {
        setIsLoading(true);
        setError(null);
        try {
            await printerService.connectBluetooth();
            setIsConnected(true);
            setDeviceName(printerService.connectedDeviceName);
        } catch (err: any) {
            setError('Error al conectar Bluetooth: ' + (err.message || 'Desconocido'));
        } finally {
            setIsLoading(false);
        }
    };

    const handleConnectUSB = async () => {
        setIsLoading(true);
        setError(null);
        try {
            await printerService.connectUSB();
            setIsConnected(true);
            setDeviceName(printerService.connectedDeviceName);
        } catch (err: any) {
            setError('Error al conectar USB: ' + (err.message || 'Desconocido'));
        } finally {
            setIsLoading(false);
        }
    };

    const handleConnectExternal = async () => {
        setIsLoading(true);
        try {
            await printerService.connectExternal();
            setIsConnected(true);
            setDeviceName(printerService.connectedDeviceName);
        } catch (err: any) {
            setError('Error al conectar app externa');
        } finally {
            setIsLoading(false);
        }
    };

    const handleConnectNetwork = async () => {
        if (!ipInput) {
            setError('Por favor ingresa la IP de la impresora');
            return;
        }
        setIsLoading(true);
        setError(null);
        try {
            await printerService.connectNetwork(ipInput);
            setIsConnected(true);
            setDeviceName(printerService.connectedDeviceName);
        } catch (err: any) {
            setError('Error: ' + (err.message || 'Desconocido'));
        } finally {
            setIsLoading(false);
        }
    };

    const handleDisconnect = async () => {
        setIsLoading(true);
        try {
            await printerService.disconnect();
            setIsConnected(false);
            setDeviceName('Ninguno');
        } catch (err: any) {
            setError('Error al desconectar');
        } finally {
            setIsLoading(false);
        }
    };

    const handleTestPrint = async () => {
        try {
            await printerService.testPrint();
        } catch (err: any) {
            setError('Error de impresión: ' + err.message);
        }
    };

    const toggleAutoPrint = () => {
        const newValue = !autoPrint;
        printerService.setAutoPrint(newValue);
        setAutoPrint(newValue);
    };

    return (
        <div style={{ padding: '1rem', width: '100%', maxWidth: '600px', margin: '0 auto', boxSizing: 'border-box' }}>
            <div style={{
                backgroundColor: 'var(--surface-color)',
                borderRadius: 'var(--radius-lg)',
                padding: '2rem',
                border: '1px solid var(--border-color)',
                boxShadow: 'var(--shadow-md)'
            }}>
                <div style={{ display: 'flex', alignItems: 'flex-start', gap: '1rem', marginBottom: '2rem', flexWrap: 'wrap' }}>
                    <div style={{
                        width: '48px',
                        height: '48px',
                        borderRadius: '12px',
                        backgroundColor: isConnected ? 'rgba(34, 197, 94, 0.1)' : 'rgba(107, 114, 128, 0.1)',
                        display: 'flex',
                        alignItems: 'center',
                        justifyContent: 'center',
                        color: isConnected ? '#22c55e' : 'var(--text-secondary)',
                        flexShrink: 0,
                    }}>
                        <Printer size={24} />
                    </div>
                    <div style={{ flex: 1, minWidth: 0 }}>
                        <h3 style={{ margin: 0, fontSize: 'clamp(1rem, 4vw, 1.25rem)', fontWeight: '700', lineHeight: 1.3 }}>Configuración de Impresora</h3>
                        <p style={{ margin: 0, color: 'var(--text-secondary)', fontSize: '0.875rem', marginTop: '0.2rem' }}>
                            {isConnected ? `Conectado a: ${deviceName}` : 'No hay ninguna impresora conectada'}
                        </p>
                    </div>
                </div>

                {error && (
                    <div style={{
                        backgroundColor: 'rgba(239, 68, 68, 0.1)',
                        color: '#ef4444',
                        padding: '1rem',
                        borderRadius: 'var(--radius-md)',
                        marginBottom: '1.5rem',
                        display: 'flex',
                        alignItems: 'center',
                        gap: '0.5rem',
                        fontSize: '0.875rem'
                    }}>
                        <AlertCircle size={18} />
                        {error}
                    </div>
                )}

                <div style={{ display: 'flex', flexDirection: 'column', gap: '1rem' }}>
                    {!isConnected ? (
                        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(140px, 1fr))', gap: '0.75rem' }}>
                            <Button
                                onClick={handleConnectBluetooth}
                                disabled={isLoading}
                                style={{ display: 'flex', gap: '0.5rem', justifyContent: 'center' }}
                            >
                                <Bluetooth size={18} /> Bluetooth (BLE)
                            </Button>
                            <Button
                                onClick={handleConnectUSB}
                                disabled={isLoading}
                                style={{ display: 'flex', gap: '0.5rem', justifyContent: 'center' }}
                            >
                                <Usb size={18} /> Cable USB
                            </Button>
                            <Button
                                onClick={handleConnectExternal}
                                disabled={isLoading}
                                style={{ display: 'flex', gap: '0.5rem', justifyContent: 'center', gridColumn: '1 / -1', backgroundColor: 'var(--secondary-color)', color: 'white' }}
                                variant="primary"
                            >
                                <Smartphone size={18} /> App RawBT (Bluetooth Clásico)
                            </Button>

                            <div style={{ 
                                gridColumn: '1 / -1', 
                                marginTop: '0.5rem',
                                padding: '1.25rem',
                                border: '2px dashed var(--border-color)',
                                borderRadius: 'var(--radius-md)',
                                backgroundColor: 'rgba(59, 130, 246, 0.05)'
                            }}>
                                <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem', marginBottom: '1rem', color: 'var(--primary-color)' }}>
                                    <Wifi size={20} />
                                    <span style={{ fontWeight: '700' }}>Impresora por Red (LAN / WIFI)</span>
                                </div>
                                <div style={{ display: 'flex', gap: '0.5rem' }}>
                                    <div style={{ flex: 1, position: 'relative' }}>
                                        <div style={{ position: 'absolute', left: '12px', top: '50%', transform: 'translateY(-50%)', color: 'var(--text-secondary)' }}>
                                            <Globe size={16} />
                                        </div>
                                        <input
                                            type="text"
                                            placeholder="Ej: 192.168.1.100"
                                            value={ipInput}
                                            onChange={(e) => setIpInput(e.target.value)}
                                            style={{
                                                width: '100%',
                                                padding: '0.75rem 0.75rem 0.75rem 2.5rem',
                                                borderRadius: 'var(--radius-md)',
                                                border: '1px solid var(--border-color)',
                                                backgroundColor: 'var(--background-color)',
                                                color: 'var(--text-primary)',
                                                fontSize: '0.9rem',
                                                outline: 'none',
                                                boxSizing: 'border-box'
                                            }}
                                        />
                                    </div>
                                    <Button 
                                        onClick={handleConnectNetwork} 
                                        disabled={isLoading}
                                        variant="primary"
                                        style={{ backgroundColor: '#3b82f6' }}
                                    >
                                        Conectar IP
                                    </Button>
                                </div>
                                <p style={{ fontSize: '0.75rem', color: 'var(--text-secondary)', marginTop: '0.75rem', lineHeight: '1.4' }}>
                                    Ideal para evitar conflictos de cables. Requiere tener instalada la app <b>RawBT</b> en Android o un bridge en PC.
                                </p>
                            </div>
                        </div>
                    ) : (
                        <div style={{ display: 'flex', flexDirection: 'column', gap: '1rem' }}>
                            <div style={{
                                display: 'flex',
                                justifyContent: 'space-between',
                                alignItems: 'center',
                                padding: '1rem',
                                backgroundColor: 'var(--background-color)',
                                borderRadius: 'var(--radius-md)',
                                border: '1px solid var(--border-color)'
                            }}>
                                <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem', color: '#22c55e', fontWeight: '600' }}>
                                    <CheckCircle2 size={18} /> Conectado
                                </div>
                                <Button variant="ghost" onClick={handleDisconnect} disabled={isLoading} style={{ color: '#ef4444' }}>
                                    <Unlink size={18} /> Desconectar
                                </Button>
                            </div>

                            <Button variant="outline" onClick={handleTestPrint} fullWidth>
                                <Printer size={18} style={{ marginRight: '0.5rem' }} /> Prueba de Impresión
                            </Button>
                        </div>
                    )}

                    <div style={{
                        marginTop: '1rem',
                        padding: '1.25rem',
                        backgroundColor: 'var(--background-color)',
                        borderRadius: 'var(--radius-md)',
                        border: '1px solid var(--border-color)',
                        display: 'flex',
                        justifyContent: 'space-between',
                        alignItems: 'center',
                        gap: '1rem',
                        flexWrap: 'wrap',
                    }}>
                        <div style={{ flex: 1, minWidth: 0 }}>
                            <div style={{ fontWeight: '600', marginBottom: '0.25rem' }}>Impresión Automática</div>
                            <div style={{ fontSize: '0.8rem', color: 'var(--text-secondary)' }}>Imprimir comanda al confirmar pedido</div>
                        </div>
                        <div onClick={toggleAutoPrint} style={{ cursor: 'pointer', color: autoPrint ? 'var(--primary-color)' : 'var(--text-secondary)', flexShrink: 0 }}>
                            {autoPrint ? <ToggleRight size={36} /> : <ToggleLeft size={36} />}
                        </div>
                    </div>
                </div>

                <div style={{ marginTop: '2rem', fontSize: '0.75rem', color: 'var(--text-secondary)', textAlign: 'center' }}>
                    <p>Compatible con impresoras térmicas ESC/POS de 58mm y 80mm.</p>
                </div>
            </div>
        </div>
    );
}

import { useState, useEffect } from 'react';
import { db } from '@/services/firebase/config';
import { collection, query, where, onSnapshot, addDoc, updateDoc, doc, deleteDoc } from 'firebase/firestore';
import { useAuth } from '@/hooks/useAuth';
import { Button, Input, Card, Badge } from '@/components/shared';
import { Trash2, Edit2, ChefHat, Plus, X, Settings2 } from 'lucide-react';
import type { Product, Category, InventoryType, UnitOfMeasure, ProductModifier, ModifierOption } from '@/types';
import { UnitOfMeasure as UC } from '@/types';
import { RecipeModal } from './RecipeModal';
import { generateUUID } from '@/utils/uuid';

export function ProductsTab() {
    const { user } = useAuth();
    const [products, setProducts] = useState<Product[]>([]);
    const [categories, setCategories] = useState<Category[]>([]);
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [editingProduct, setEditingProduct] = useState<Product | null>(null);
    const [recipeModalOpen, setRecipeModalOpen] = useState(false);
    const [recipeProduct, setRecipeProduct] = useState<Product | null>(null);
    const [modifiers, setModifiers] = useState<ProductModifier[]>([]);

    const UNIT_OPTIONS: { value: UnitOfMeasure; label: string }[] = [
        { value: UC.UNIT, label: 'Unidad' },
        { value: UC.GRAM, label: 'Gramos (g)' },
        { value: UC.KILOGRAM, label: 'Kilogramos (kg)' },
        { value: UC.LITER, label: 'Litros (L)' },
        { value: UC.MILLILITER, label: 'Mililitros (mL)' },
        { value: UC.PIECE, label: 'Piezas' },
        { value: UC.BOTTLE, label: 'Botellas' },
    ];

    // Form State
    const [formData, setFormData] = useState({
        name: '',
        nameEn: '',
        price: '',
        category: '',
        description: '',
        descriptionEn: '',
        available: true,
        isPopular: false,
        controlaStock: false,
        stockActual: '',
        stockMinimo: '',
        stockMaximo: '',
        tipoInventario: 'product' as InventoryType,
        unidadMedida: UC.UNIT as UnitOfMeasure,
        dietaryTags: [] as string[],
    });

    const DIETARY_OPTIONS = [
        { tag: 'vegan', label: '🌿 Vegano' },
        { tag: 'vegetarian', label: '🥦 Vegetariano' },
        { tag: 'spicy', label: '🌶️ Picante' },
        { tag: 'gluten-free', label: '🌾 Sin Gluten' },
        { tag: 'dairy-free', label: '🥛 Sin Lácteos' },
        { tag: 'nut-free', label: '🥜 Sin Nueces' },
    ];

    useEffect(() => {
        if (!user?.restaurantId) return;

        const pQuery = query(
            collection(db, 'products'),
            where('restaurantId', '==', user.restaurantId)
        );

        const unsubscribeProducts = onSnapshot(pQuery, (snapshot) => {
            const data = snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() } as Product));
            setProducts(data);
        });

        // Fetch Categories
        const cQuery = query(
            collection(db, 'categories'),
            where('restaurantId', '==', user.restaurantId)
        );

        const unsubscribeCategories = onSnapshot(cQuery, (snapshot) => {
            const data = snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() } as Category));
            setCategories(data.sort((a, b) => a.name.localeCompare(b.name)));

            // Set initial category if not set
            if (data.length > 0 && !formData.category) {
                setFormData(prev => ({ ...prev, category: data[0].name }));
            }
        });

        return () => {
            unsubscribeProducts();
            unsubscribeCategories();
        };
    }, [user?.restaurantId]);

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        try {
            const productData = {
                restaurantId: user?.restaurantId,
                name: formData.name,
                nameEn: formData.nameEn.trim(),
                price: parseFloat(formData.price),
                category: formData.category,
                description: formData.description.trim(),
                descriptionEn: formData.descriptionEn.trim(),
                available: formData.available,
                isPopular: formData.isPopular,
                controlaStock: formData.controlaStock,
                tipoInventario: formData.controlaStock ? formData.tipoInventario : 'product',
                unidadMedida: formData.controlaStock && formData.tipoInventario === 'product' ? formData.unidadMedida : 'unidad',
                stockActual: formData.controlaStock && formData.tipoInventario === 'product' ? (formData.stockActual === '' ? 0 : parseFloat(formData.stockActual) || 0) : 0,
                stockMinimo: formData.controlaStock && formData.tipoInventario === 'product' ? (formData.stockMinimo === '' ? 0 : parseFloat(formData.stockMinimo) || 0) : 0,
                stockMaximo: formData.controlaStock && formData.tipoInventario === 'product' && formData.stockMaximo ? parseFloat(formData.stockMaximo) : 0,
                fechaActualizacionStock: new Date(),
                dietaryTags: formData.dietaryTags,
                modifiers: modifiers.filter(m => m.name.trim() && m.options.length > 0),
            };

            if (editingProduct) {
                await updateDoc(doc(db, 'products', editingProduct.id), productData);
            } else {
                await addDoc(collection(db, 'products'), productData);
            }

            closeModal();
        } catch (error) {
            console.error(error);
            alert("Error al guardar producto");
        }
    };

    const handleDelete = async (id: string) => {
        if (confirm('¿Eliminar producto?')) {
            await deleteDoc(doc(db, 'products', id));
        }
    };

    const openModal = (product?: Product) => {
        if (product) {
            setEditingProduct(product);
            setFormData({
                name: product.name,
                nameEn: product.nameEn || '',
                price: product.price.toString(),
                category: product.category,
                description: product.description || '',
                descriptionEn: product.descriptionEn || '',
                available: product.available,
                isPopular: product.isPopular || false,
                controlaStock: product.controlaStock || false,
                stockActual: product.stockActual !== undefined ? product.stockActual.toString() : '',
                stockMinimo: product.stockMinimo !== undefined ? product.stockMinimo.toString() : '',
                stockMaximo: product.stockMaximo !== undefined ? product.stockMaximo.toString() : '',
                tipoInventario: product.tipoInventario || 'product',
                unidadMedida: product.unidadMedida || UC.UNIT,
                dietaryTags: product.dietaryTags || [],
            });
            setModifiers(product.modifiers || []);
        } else {
            setEditingProduct(null);
            setFormData({
                name: '',
                nameEn: '',
                price: '',
                category: categories.length > 0 ? categories[0].name : '',
                description: '',
                descriptionEn: '',
                available: true,
                isPopular: false,
                controlaStock: false,
                stockActual: '',
                stockMinimo: '',
                stockMaximo: '',
                tipoInventario: 'product',
                unidadMedida: UC.UNIT,
                dietaryTags: [],
            });
            setModifiers([]);
        }
        setIsModalOpen(true);
    };

    // ── Modifier helpers ──
    const addModifier = () => {
        setModifiers(prev => [...prev, {
            id: generateUUID(),
            name: '',
            options: [{ name: '', price: 0 }],
            required: false,
            multiple: true,
            minSelections: 0,
            maxSelections: 1,
        }]);
    };

    const updateModifier = (idx: number, patch: Partial<ProductModifier>) => {
        setModifiers(prev => prev.map((m, i) => i === idx ? { ...m, ...patch } : m));
    };

    const removeModifier = (idx: number) => {
        setModifiers(prev => prev.filter((_, i) => i !== idx));
    };

    const addOption = (modIdx: number) => {
        setModifiers(prev => prev.map((m, i) =>
            i === modIdx ? { ...m, options: [...m.options, { name: '', price: 0 }] } : m
        ));
    };

    const updateOption = (modIdx: number, optIdx: number, patch: Partial<ModifierOption>) => {
        setModifiers(prev => prev.map((m, i) =>
            i === modIdx ? { ...m, options: m.options.map((o, j) => j === optIdx ? { ...o, ...patch } : o) } : m
        ));
    };

    const removeOption = (modIdx: number, optIdx: number) => {
        setModifiers(prev => prev.map((m, i) =>
            i === modIdx ? { ...m, options: m.options.filter((_, j) => j !== optIdx) } : m
        ));
    };

    const closeModal = () => {
        setIsModalOpen(false);
        setEditingProduct(null);
    };

    return (
        <div>
            <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '1rem' }}>
                <h3>Inventario ({products.length})</h3>
                <Button onClick={() => openModal()}>+ Nuevo Producto</Button>
            </div>

            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(200px, 1fr))', gap: '1rem' }}>
                {products.map(product => (
                    <Card key={product.id} style={{ padding: '1rem', position: 'relative', opacity: product.available ? 1 : 0.6 }}>
                        <div style={{ fontWeight: 'bold', display: 'flex', alignItems: 'center', gap: '0.5rem', flexWrap: 'wrap' }}>
                            {product.name}
                            {product.isPopular && <span title="Popular">⭐</span>}
                            {product.tipoInventario === 'recipe' && <span title="Tiene receta"><ChefHat size={14} color="var(--primary-color)" /></span>}
                            {(product.dietaryTags || []).map(tag => (
                                <span key={tag} title={tag} style={{ fontSize: '0.85rem' }}>
                                    {tag === 'vegan' ? '🌿' : tag === 'vegetarian' ? '🥦' : tag === 'spicy' ? '🌶️' : tag === 'gluten-free' ? '🌾' : tag === 'dairy-free' ? '🥛' : tag === 'nut-free' ? '🥜' : ''}
                                </span>
                            ))}
                        </div>
                        <div style={{ color: 'var(--color-primary)', fontSize: '1.2rem' }}>S/ {product.price.toFixed(2)}</div>
                        <div style={{ fontSize: '0.8rem', color: '#666' }}>{product.category}</div>
                        {product.description && (
                            <div style={{ fontSize: '0.78rem', color: '#999', fontStyle: 'italic', marginTop: '0.3rem', lineHeight: 1.4 }}>
                                {product.description}
                            </div>
                        )}
                        <div style={{ marginTop: '1rem', display: 'flex', gap: '0.5rem' }}>
                            <Button size="sm" variant="outline" onClick={() => openModal(product)}><Edit2 size={14} className="mr-1" /> Editar</Button>
                            {product.tipoInventario === 'recipe' && (
                                <Button size="sm" variant="outline" onClick={() => { setRecipeProduct(product); setRecipeModalOpen(true); }}
                                    style={{ display: 'flex', alignItems: 'center', gap: '0.25rem', color: 'var(--primary-color)', borderColor: 'var(--primary-color)' }}>
                                    <ChefHat size={14} />
                                </Button>
                            )}
                            <Button size="sm" variant="danger" onClick={() => handleDelete(product.id)}><Trash2 size={14} /></Button>
                        </div>
                        {!product.available && <Badge variant="warning" style={{ position: 'absolute', top: 5, right: 5 }}>Agotado</Badge>}
                    </Card>
                ))}
            </div>

            {/* Modal Simple implementation inline for speed */}
            {isModalOpen && (
                <div style={{
                    position: 'fixed', top: 0, left: 0, right: 0, bottom: 0,
                    background: 'rgba(0,0,0,0.5)', display: 'flex', alignItems: 'center', justifyContent: 'center', zIndex: 1000
                }}>
                    <Card style={{ padding: '1.5rem 2rem', width: '450px', maxWidth: '90%', maxHeight: '90vh', overflowY: 'auto' }}>
                        <h2 style={{ marginBottom: '1.25rem' }}>{editingProduct ? 'Editar' : 'Nuevo'} Producto</h2>
                        <form onSubmit={handleSubmit} style={{ display: 'flex', flexDirection: 'column', gap: '1rem' }}>
                            <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '1rem' }}>
                                <Input
                                    label="Nombre (ES)"
                                    value={formData.name}
                                    onChange={e => setFormData({ ...formData, name: e.target.value })}
                                    required
                                    placeholder="Ceviche Clásico"
                                />
                                <Input
                                    label="Nombre (EN) - Opcional"
                                    value={formData.nameEn}
                                    onChange={e => setFormData({ ...formData, nameEn: e.target.value })}
                                    placeholder="Classic Ceviche"
                                />
                            </div>

                            <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '1rem' }}>
                                <Input
                                    label="Precio (S/)"
                                    type="number"
                                    step="0.1"
                                    value={formData.price}
                                    onChange={e => setFormData({ ...formData, price: e.target.value })}
                                    required
                                />
                                <div>
                                    <label style={{ display: 'block', marginBottom: '0.5rem', fontSize: '0.9rem', fontWeight: 'bold' }}>Categoría</label>
                                    <select
                                        style={{
                                            width: '100%',
                                            padding: '0.56rem',
                                            borderRadius: '8px',
                                            border: '1px solid var(--divider-color)',
                                            background: 'var(--background-color)',
                                            color: 'var(--text-primary)',
                                            fontSize: '0.9rem'
                                        }}
                                        value={formData.category}
                                        onChange={e => setFormData({ ...formData, category: e.target.value })}
                                        required
                                    >
                                        {categories.length === 0 && <option value="">Crear categoría primero...</option>}
                                        {categories.map(cat => (
                                            <option key={cat.id} value={cat.name}>{cat.name}</option>
                                        ))}
                                    </select>
                                </div>
                            </div>

                            <div>
                                <label style={{ display: 'block', marginBottom: '0.4rem', fontSize: '0.9rem', fontWeight: '700', color: 'var(--text-primary)' }}>
                                    Descripción (Español)
                                </label>
                                <textarea
                                    value={formData.description}
                                    onChange={e => setFormData({ ...formData, description: e.target.value })}
                                    placeholder="Ej: Tiradito de corvina marinado en leche de tigre..."
                                    rows={2}
                                    maxLength={200}
                                    style={{
                                        width: '100%',
                                        padding: '0.6rem 0.75rem',
                                        borderRadius: '8px',
                                        border: '1px solid var(--divider-color)',
                                        fontSize: '0.88rem',
                                        fontFamily: 'inherit',
                                        resize: 'vertical',
                                        lineHeight: 1.5,
                                        color: 'var(--text-primary)',
                                        background: 'var(--background-color)',
                                        outline: 'none',
                                        boxSizing: 'border-box',
                                    }}
                                />
                            </div>

                            <div>
                                <label style={{ display: 'block', marginBottom: '0.4rem', fontSize: '0.9rem', fontWeight: '700', color: 'var(--text-primary)' }}>
                                    Descripción (Inglés) - Opcional
                                </label>
                                <textarea
                                    value={formData.descriptionEn}
                                    onChange={e => setFormData({ ...formData, descriptionEn: e.target.value })}
                                    placeholder="Example: Sea bass tiradito marinated in tiger's milk..."
                                    rows={2}
                                    maxLength={200}
                                    style={{
                                        width: '100%',
                                        padding: '0.6rem 0.75rem',
                                        borderRadius: '8px',
                                        border: '1px solid var(--divider-color)',
                                        fontSize: '0.88rem',
                                        fontFamily: 'inherit',
                                        resize: 'vertical',
                                        lineHeight: 1.5,
                                        color: 'var(--text-primary)',
                                        background: 'var(--background-color)',
                                        outline: 'none',
                                        boxSizing: 'border-box',
                                    }}
                                />
                            </div>

                            <div style={{ display: 'flex', gap: '1.5rem', marginTop: '0.5rem' }}>
                                <label style={{ display: 'flex', alignItems: 'center', gap: '0.5rem', cursor: 'pointer', fontSize: '0.9rem' }}>
                                    <input
                                        type="checkbox"
                                        checked={formData.available}
                                        onChange={e => setFormData({ ...formData, available: e.target.checked })}
                                    />
                                    Disponible
                                </label>

                                <label style={{ display: 'flex', alignItems: 'center', gap: '0.5rem', cursor: 'pointer', fontSize: '0.9rem' }}>
                                    <input
                                        type="checkbox"
                                        checked={formData.isPopular}
                                        onChange={e => setFormData({ ...formData, isPopular: e.target.checked })}
                                    />
                                    ⭐ Popular
                                </label>
                            </div>

                            <div style={{ padding: '1rem', border: '1px solid var(--divider-color)', borderRadius: '8px', background: 'var(--surface-color)', marginTop: '0.5rem' }}>
                                <label style={{ display: 'flex', alignItems: 'center', gap: '0.5rem', cursor: 'pointer', fontSize: '1rem', fontWeight: 'bold' }}>
                                    <input
                                        type="checkbox"
                                        checked={formData.controlaStock}
                                        onChange={e => setFormData({ ...formData, controlaStock: e.target.checked })}
                                    />
                                    Controlar Stock (Inventario)
                                </label>

                                {formData.controlaStock && (
                                    <div style={{ marginTop: '1rem', display: 'flex', flexDirection: 'column', gap: '1rem' }}>
                                        {/* Inventory Type Selector */}
                                        <div>
                                            <label style={{ display: 'block', marginBottom: '0.5rem', fontSize: '0.9rem', fontWeight: 700 }}>Tipo de Inventario</label>
                                            <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '0.5rem' }}>
                                                {([['product', '📦 Producto', 'Stock directo del producto'] as const, ['recipe', '🍳 Receta', 'Descuenta insumos al vender'] as const]).map(([val, lbl, desc]) => (
                                                    <label key={val} style={{
                                                        display: 'flex', flexDirection: 'column', gap: '0.2rem',
                                                        padding: '0.75rem', borderRadius: '8px', cursor: 'pointer',
                                                        border: `2px solid ${formData.tipoInventario === val ? 'var(--primary-color)' : 'var(--divider-color)'}`,
                                                        background: formData.tipoInventario === val ? 'rgba(37, 99, 235, 0.04)' : 'transparent',
                                                    }}>
                                                        <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
                                                            <input type="radio" name="tipoInventario" checked={formData.tipoInventario === val}
                                                                onChange={() => setFormData({ ...formData, tipoInventario: val })} />
                                                            <span style={{ fontWeight: 600, fontSize: '0.9rem' }}>{lbl}</span>
                                                        </div>
                                                        <span style={{ fontSize: '0.76rem', color: 'var(--text-secondary)', marginLeft: '1.5rem' }}>{desc}</span>
                                                    </label>
                                                ))}
                                            </div>
                                        </div>

                                        {/* Simple Product Stock Fields */}
                                        {formData.tipoInventario === 'product' && (
                                            <>
                                                <div>
                                                    <label style={{ display: 'block', marginBottom: '0.5rem', fontSize: '0.9rem', fontWeight: 700 }}>Unidad de Medida</label>
                                                    <select
                                                        value={formData.unidadMedida}
                                                        onChange={e => setFormData({ ...formData, unidadMedida: e.target.value as UnitOfMeasure })}
                                                        style={{ width: '100%', padding: '0.56rem', borderRadius: '8px', border: '1px solid var(--divider-color)', background: 'var(--background-color)', color: 'var(--text-primary)', fontSize: '0.9rem' }}
                                                    >
                                                        {UNIT_OPTIONS.map(u => <option key={u.value} value={u.value}>{u.label}</option>)}
                                                    </select>
                                                </div>
                                                <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr 1fr', gap: '1rem' }}>
                                                    <Input label="Stock Actual" type="number" min="0" step="0.01" value={formData.stockActual}
                                                        onChange={e => setFormData({ ...formData, stockActual: e.target.value })} required placeholder="50" />
                                                    <Input label="Stock Mínimo" type="number" min="0" step="0.01" value={formData.stockMinimo}
                                                        onChange={e => setFormData({ ...formData, stockMinimo: e.target.value })} required placeholder="10" />
                                                    <Input label="Stock Máximo" type="number" min="0" step="0.01" value={formData.stockMaximo}
                                                        onChange={e => setFormData({ ...formData, stockMaximo: e.target.value })} placeholder="Opcional" />
                                                </div>
                                            </>
                                        )}

                                        {/* Recipe Type Info */}
                                        {formData.tipoInventario === 'recipe' && (
                                            <div style={{ padding: '0.75rem 1rem', background: 'rgba(37, 99, 235, 0.05)', borderRadius: '8px', border: '1px dashed var(--primary-color)' }}>
                                                <p style={{ margin: 0, fontSize: '0.85rem', color: 'var(--text-secondary)' }}>
                                                    <ChefHat size={14} style={{ verticalAlign: 'middle', marginRight: '0.25rem' }} />
                                                    Guarda el producto y luego usa el botón <strong>"Receta"</strong> en la lista para configurar sus ingredientes.
                                                </p>
                                            </div>
                                        )}
                                    </div>
                                )}
                            </div>

                            {/* Dietary Tags */}
                            <div>
                                <label style={{ display: 'block', marginBottom: '0.5rem', fontSize: '0.9rem', fontWeight: '700', color: 'var(--text-primary)' }}>
                                    Etiquetas Dietéticas / Alérgenos
                                </label>
                                <div style={{ display: 'grid', gridTemplateColumns: 'repeat(3, 1fr)', gap: '0.4rem' }}>
                                    {DIETARY_OPTIONS.map(opt => {
                                        const active = formData.dietaryTags.includes(opt.tag);
                                        return (
                                            <button
                                                key={opt.tag}
                                                type="button"
                                                onClick={() => {
                                                    const newTags = active
                                                        ? formData.dietaryTags.filter(t => t !== opt.tag)
                                                        : [...formData.dietaryTags, opt.tag];
                                                    setFormData({ ...formData, dietaryTags: newTags });
                                                }}
                                                style={{
                                                    padding: '0.4rem 0.5rem',
                                                    borderRadius: '8px',
                                                    border: active ? '2px solid var(--primary-color)' : '1.5px solid var(--divider-color)',
                                                    background: active ? 'color-mix(in srgb, var(--primary-color) 10%, white)' : 'transparent',
                                                    color: active ? 'var(--primary-color)' : 'var(--text-secondary)',
                                                    fontSize: '0.78rem',
                                                    fontWeight: active ? 700 : 500,
                                                    cursor: 'pointer',
                                                    transition: 'all 0.15s',
                                                }}
                                            >
                                                {opt.label}
                                            </button>
                                        );
                                    })}
                                </div>
                            </div>

                            {/* ── Modifier Editor ── */}
                            <div style={{ padding: '1rem', border: '1px solid var(--divider-color)', borderRadius: '8px', background: 'var(--surface-color)', marginTop: '0.5rem' }}>
                                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: modifiers.length > 0 ? '0.75rem' : 0 }}>
                                    <label style={{ display: 'flex', alignItems: 'center', gap: '0.5rem', fontSize: '1rem', fontWeight: 'bold', color: 'var(--text-primary)' }}>
                                        <Settings2 size={16} /> Modificadores
                                    </label>
                                    <button
                                        type="button"
                                        onClick={addModifier}
                                        style={{
                                            display: 'flex', alignItems: 'center', gap: '0.3rem',
                                            padding: '0.35rem 0.75rem', borderRadius: '6px',
                                            border: '1px dashed var(--primary-color)', background: 'transparent',
                                            color: 'var(--primary-color)', fontSize: '0.8rem', fontWeight: 600,
                                            cursor: 'pointer'
                                        }}
                                    >
                                        <Plus size={14} /> Añadir
                                    </button>
                                </div>

                                {modifiers.map((mod, modIdx) => (
                                    <div key={mod.id} style={{
                                        padding: '0.75rem', border: '1px solid var(--divider-color)',
                                        borderRadius: '8px', marginBottom: '0.75rem',
                                        background: 'var(--background-color)'
                                    }}>
                                        {/* Modifier header */}
                                        <div style={{ display: 'flex', gap: '0.5rem', alignItems: 'center', marginBottom: '0.5rem' }}>
                                            <input
                                                type="text"
                                                value={mod.name}
                                                onChange={e => updateModifier(modIdx, { name: e.target.value })}
                                                placeholder="Ej: Sabores, Toppings, Salsas..."
                                                style={{
                                                    flex: 1, padding: '0.4rem 0.6rem', borderRadius: '6px',
                                                    border: '1px solid var(--divider-color)',
                                                    background: 'var(--surface-color)', color: 'var(--text-primary)',
                                                    fontSize: '0.88rem', fontWeight: 600
                                                }}
                                            />
                                            <button type="button" onClick={() => removeModifier(modIdx)} style={{
                                                background: 'transparent', border: 'none', color: 'var(--danger-color)',
                                                cursor: 'pointer', padding: '0.25rem'
                                            }}>
                                                <Trash2 size={16} />
                                            </button>
                                        </div>

                                        {/* Modifier config row */}
                                        <div style={{ display: 'flex', gap: '0.5rem', flexWrap: 'wrap', alignItems: 'center', marginBottom: '0.5rem' }}>
                                            <label style={{ display: 'flex', alignItems: 'center', gap: '0.3rem', fontSize: '0.78rem', cursor: 'pointer' }}>
                                                <input type="checkbox" checked={mod.required || false}
                                                    onChange={e => updateModifier(modIdx, { required: e.target.checked, minSelections: e.target.checked ? Math.max(mod.minSelections || 0, 1) : 0 })} />
                                                Obligatorio
                                            </label>
                                            <div style={{ display: 'flex', alignItems: 'center', gap: '0.3rem', fontSize: '0.78rem' }}>
                                                <span>Mín:</span>
                                                <input type="number" min={0} max={20} value={mod.minSelections || 0}
                                                    onChange={e => updateModifier(modIdx, { minSelections: parseInt(e.target.value) || 0, required: parseInt(e.target.value) > 0 })}
                                                    style={{ width: '42px', padding: '0.2rem 0.35rem', borderRadius: '4px', border: '1px solid var(--divider-color)', textAlign: 'center', fontSize: '0.82rem', background: 'var(--surface-color)', color: 'var(--text-primary)' }} />
                                            </div>
                                            <div style={{ display: 'flex', alignItems: 'center', gap: '0.3rem', fontSize: '0.78rem' }}>
                                                <span>Máx:</span>
                                                <input type="number" min={1} max={20} value={mod.maxSelections || 1}
                                                    onChange={e => updateModifier(modIdx, { maxSelections: parseInt(e.target.value) || 1, multiple: parseInt(e.target.value) > 1 })}
                                                    style={{ width: '42px', padding: '0.2rem 0.35rem', borderRadius: '4px', border: '1px solid var(--divider-color)', textAlign: 'center', fontSize: '0.82rem', background: 'var(--surface-color)', color: 'var(--text-primary)' }} />
                                            </div>
                                        </div>

                                        {/* Options list */}
                                        {mod.options.map((opt, optIdx) => (
                                            <div key={optIdx} style={{ display: 'flex', gap: '0.4rem', alignItems: 'center', marginBottom: '0.3rem' }}>
                                                <input
                                                    type="text"
                                                    value={opt.name}
                                                    onChange={e => updateOption(modIdx, optIdx, { name: e.target.value })}
                                                    placeholder="Nombre opción"
                                                    style={{
                                                        flex: 1, padding: '0.35rem 0.5rem', borderRadius: '5px',
                                                        border: '1px solid var(--divider-color)', fontSize: '0.82rem',
                                                        background: 'var(--surface-color)', color: 'var(--text-primary)'
                                                    }}
                                                />
                                                <input
                                                    type="number"
                                                    min={0}
                                                    step="0.1"
                                                    value={opt.price || 0}
                                                    onChange={e => updateOption(modIdx, optIdx, { price: parseFloat(e.target.value) || 0 })}
                                                    placeholder="+S/"
                                                    style={{
                                                        width: '60px', padding: '0.35rem 0.4rem', borderRadius: '5px',
                                                        border: '1px solid var(--divider-color)', textAlign: 'center',
                                                        fontSize: '0.82rem', background: 'var(--surface-color)', color: 'var(--text-primary)'
                                                    }}
                                                />
                                                <button type="button" onClick={() => removeOption(modIdx, optIdx)} style={{
                                                    background: 'transparent', border: 'none', color: 'var(--text-secondary)',
                                                    cursor: 'pointer', padding: '0.2rem'
                                                }}>
                                                    <X size={14} />
                                                </button>
                                            </div>
                                        ))}
                                        <button
                                            type="button"
                                            onClick={() => addOption(modIdx)}
                                            style={{
                                                display: 'flex', alignItems: 'center', gap: '0.3rem',
                                                padding: '0.25rem 0.5rem', border: 'none',
                                                background: 'transparent', color: 'var(--primary-color)',
                                                fontSize: '0.78rem', fontWeight: 600, cursor: 'pointer', marginTop: '0.2rem'
                                            }}
                                        >
                                            <Plus size={12} /> Opción
                                        </button>
                                    </div>
                                ))}

                                {modifiers.length === 0 && (
                                    <p style={{ fontSize: '0.8rem', color: 'var(--text-secondary)', margin: '0.25rem 0 0', fontStyle: 'italic' }}>
                                        Sin modificadores. Usa esto para agregar sabores, toppings, extras, etc.
                                    </p>
                                )}
                            </div>

                            <div style={{ display: 'flex', gap: '1rem', marginTop: '1rem' }}>
                                <Button type="button" variant="ghost" onClick={closeModal} fullWidth>Cancelar</Button>
                                <Button type="submit" fullWidth>Guardar Producto</Button>
                            </div>
                        </form>
                    </Card>
                </div>
            )}

            {/* Recipe Modal */}
            {recipeProduct && (
                <RecipeModal
                    productId={recipeProduct.id}
                    productName={recipeProduct.name}
                    isOpen={recipeModalOpen}
                    onClose={() => { setRecipeModalOpen(false); setRecipeProduct(null); }}
                />
            )}
        </div>
    );
}

import { Button } from '@/components/shared';
import { OrderCard } from '@/components/features/OrderCard';
import { useOrders } from '@/hooks/useOrders';
import { X, Pencil, Table2, CheckCircle2 } from 'lucide-react';
import type { RestaurantTable } from '@/types';

interface TableDetailModalProps {
    table: RestaurantTable;
    onClose: () => void;
    onEdit?: (order: any) => void;
}

export function TableDetailModal({ table, onClose, onEdit }: TableDetailModalProps) {
    const { activeOrders } = useOrders();
    
    // For takeout orders (table.number === 0), we must rely ONLY on the exact ID.
    // For physical tables, we can fallback to finding by table number if ID isn't linked yet.
    const activeOrder = table.number === 0
        ? activeOrders?.find(o => o.id === table.currentOrderId)
        : activeOrders?.find(o => o.tableNumber === table.number);

    const isFree = table.status === 'free';
    const statusColor = isFree ? 'var(--success-color)' : 'var(--warning-color)';
    const statusBg = isFree ? 'rgba(127, 176, 105, 0.1)' : 'rgba(220, 158, 130, 0.15)';
    const isTakeout = table.number === 0;

    return (
        <div style={{
            position: 'fixed', top: 0, left: 0, right: 0, bottom: 0,
            backgroundColor: 'rgba(255, 255, 255, 0.8)', display: 'flex',
            justifyContent: 'center', alignItems: 'center', zIndex: 1000,
            backdropFilter: 'blur(16px)',
            padding: '1rem'
        }}>
            <div style={{
                width: '100%',
                maxWidth: '450px',
                maxHeight: '90vh',
                overflowY: 'auto',
                backgroundColor: 'var(--surface-color)',
                border: `2px solid ${statusColor}`,
                borderRadius: 'var(--radius-lg)',
                color: 'var(--text-primary)',
                boxShadow: `0 20px 50px ${isFree ? 'rgba(127, 176, 105, 0.2)' : 'rgba(220, 158, 130, 0.25)'}`,
                scrollbarWidth: 'none'
            }}>
                <div style={{
                    padding: '1.5rem 1.75rem',
                    borderBottom: '1px solid var(--divider-color)',
                    display: 'flex',
                    justifyContent: 'space-between',
                    alignItems: 'center',
                    background: statusBg,
                    borderTopLeftRadius: 'var(--radius-lg)',
                    borderTopRightRadius: 'var(--radius-lg)'
                }}>
                    <div style={{ display: 'flex', alignItems: 'center', gap: 'var(--spacing-md)' }}>
                        <div style={{
                            width: '48px',
                            height: '44px',
                            borderRadius: '12px',
                            background: statusColor,
                            color: 'white',
                            display: 'flex',
                            flexDirection: 'column',
                            alignItems: 'center',
                            justifyContent: 'center',
                            fontWeight: '900',
                            fontSize: '1rem',
                            boxShadow: '0 4px 10px rgba(0,0,0,0.1)',
                            lineHeight: 1
                        }}>
                            <Table2 size={16} />
                            <span>{isTakeout ? 'LL' : table.number}</span>
                        </div>
                        <div>
                            <h3 style={{ margin: 0, fontSize: '1.25rem', fontWeight: '800', color: 'var(--text-primary)' }}>
                                {isTakeout ? 'Para Llevar' : `Mesa ${table.number}`}
                            </h3>
                            <span style={{ fontSize: '0.75rem', fontWeight: '800', textTransform: 'uppercase', color: statusColor, letterSpacing: '0.05em' }}>
                                {isFree ? (isTakeout ? 'Completado' : 'Disponible') : 'En Servicio'}
                            </span>
                        </div>
                    </div>
                    <button onClick={onClose} style={{
                        background: 'var(--divider-color)',
                        border: 'none',
                        color: 'var(--text-secondary)',
                        cursor: 'pointer',
                        width: '32px',
                        height: '32px',
                        borderRadius: '50%',
                        display: 'flex',
                        alignItems: 'center',
                        justifyContent: 'center'
                    }}>
                        <X size={20} />
                    </button>
                </div>

                <div style={{ padding: '1.5rem' }}>
                    {activeOrder ? (
                        <>
                            <div style={{ marginBottom: '1.5rem' }}>
                                <OrderCard order={activeOrder} />
                            </div>
                            <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '1rem' }}>
                                <Button variant="outline" onClick={onClose} style={{ borderRadius: 'var(--radius-md)' }}>
                                    Cerrar
                                </Button>
                                {activeOrder.status !== 'paid' && onEdit && (
                                    <Button
                                        variant="primary"
                                        onClick={() => onEdit(activeOrder)}
                                        style={{
                                            background: 'var(--primary-color)',
                                            display: 'flex',
                                            alignItems: 'center',
                                            justifyContent: 'center',
                                            gap: '0.5rem',
                                            borderRadius: 'var(--radius-md)',
                                            fontWeight: '700'
                                        }}
                                    >
                                        <Pencil size={18} /> Editar
                                    </Button>
                                )}
                            </div>
                        </>
                    ) : (
                        <div style={{ textAlign: 'center', padding: '2rem', color: 'var(--text-secondary)' }}>
                            <div style={{
                                width: '64px',
                                height: '64px',
                                background: isTakeout ? 'rgba(67, 160, 71, 0.1)' : 'var(--divider-color)',
                                borderRadius: '50%',
                                display: 'flex',
                                alignItems: 'center',
                                justifyContent: 'center',
                                margin: '0 auto 1.5rem',
                                color: isTakeout ? 'var(--success-color)' : 'var(--text-secondary)'
                            }}>
                                {isTakeout ? <CheckCircle2 size={32} /> : <X size={32} />}
                            </div>
                            <p style={{ marginBottom: '1.5rem', fontWeight: '600', fontSize: '1.1rem', color: 'var(--text-primary)' }}>
                                {isTakeout ? '¡Pedido Completado!' : 'Esta mesa no tiene pedidos activos.'}
                            </p>
                            <Button variant="primary" onClick={onClose} style={{
                                background: isTakeout ? 'var(--success-color)' : 'var(--primary-color)', 
                                width: '100%',
                                borderRadius: 'var(--radius-md)',
                                fontWeight: '700',
                                height: '48px'
                            }}>
                                {isTakeout ? 'Cerrar' : 'Entendido'}
                            </Button>
                        </div>
                    )}
                </div>
            </div>
        </div>
    );
}

import { useState, useEffect } from 'react';
import { db } from '@/services/firebase/config';
import { collection, query, where, onSnapshot, addDoc, doc, deleteDoc, updateDoc, getDocs } from 'firebase/firestore';
import { useAuth } from '@/hooks/useAuth';
import { useBranch } from '@/app/providers/BranchProvider';
import { useTenant } from '@/app/providers/TenantProvider';
import { Button, Input, Card, Badge } from '@/components/shared';
import { Trash2, Pencil, Building2, Users, Filter } from 'lucide-react';
import { hashPin } from '@/utils/crypto';
import type { User } from '@/types';

export function UsersTab() {
    const { user: currentUser } = useAuth();
    const { tenant } = useTenant();
    const { allBranches, isMultiBranch } = useBranch();

    const [users, setUsers] = useState<User[]>([]);
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [editingUserId, setEditingUserId] = useState<string | null>(null);
    const [filterBranch, setFilterBranch] = useState<string>('all');

    // Form State
    const [formData, setFormData] = useState<{
        name: string;
        pin: string;
        role: 'admin' | 'waiter' | 'chef' | 'shift_manager' | 'caja';
        restaurantId: string;
    }>({
        name: '',
        pin: '',
        role: 'waiter',
        restaurantId: currentUser?.restaurantId || '',
    });

    // Get all restaurant IDs to monitor
    const allRestaurantIds = isMultiBranch && tenant?.branches
        ? [tenant.id, ...tenant.branches]
        : [currentUser?.restaurantId || ''];

    useEffect(() => {
        if (!currentUser?.restaurantId) return;

        // For multi-branch: listen to users across all branches
        // For single: just current restaurant
        const idsToWatch = allRestaurantIds.filter(Boolean);

        if (idsToWatch.length === 0) return;

        // Firestore 'in' supports up to 30 values
        const q = query(
            collection(db, 'users'),
            where('restaurantId', 'in', idsToWatch.slice(0, 30))
        );

        const unsubscribe = onSnapshot(q, (snapshot) => {
            const data = snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() } as User));
            setUsers(data);
        });

        return () => unsubscribe();
    }, [currentUser?.restaurantId, allRestaurantIds.length]);

    // Filter by branch
    const filteredUsers = filterBranch === 'all'
        ? users
        : users.filter(u => u.restaurantId === filterBranch);

    // Get branch name by ID
    const getBranchName = (restaurantId: string): string => {
        if (restaurantId === tenant?.id) return tenant.name || 'Principal';
        const branch = allBranches.find(b => b.id === restaurantId);
        return branch?.name || restaurantId;
    };

    // Group users by branch for stats
    const usersByBranch = allRestaurantIds.reduce((acc, branchId) => {
        acc[branchId] = users.filter(u => u.restaurantId === branchId);
        return acc;
    }, {} as Record<string, User[]>);

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        try {
            if (!/^\d{4}$/.test(formData.pin)) {
                alert("El PIN debe tener 4 dígitos numéricos");
                return;
            }

            const targetRestaurantId = isMultiBranch ? formData.restaurantId : currentUser?.restaurantId;

            const newHash = await hashPin(formData.pin);

            // PIN collision check within target branch
            const usersRef = collection(db, 'users');
            const q = query(usersRef, where('restaurantId', '==', targetRestaurantId));
            const querySnapshot = await getDocs(q);

            const collision = querySnapshot.docs.some(doc => {
                if (editingUserId && doc.id === editingUserId) return false;
                const data = doc.data();
                return data.pinHash === newHash || data.pinHash === formData.pin;
            });

            if (collision) {
                alert("Este PIN ya está en uso por otro miembro en esa sucursal.");
                return;
            }

            const userData = {
                restaurantId: targetRestaurantId,
                name: formData.name,
                pinHash: newHash,
                role: formData.role
            };

            if (editingUserId) {
                await updateDoc(doc(db, 'users', editingUserId), userData);
            } else {
                await addDoc(collection(db, 'users'), userData);
            }
            closeModal();
        } catch (error) {
            console.error(error);
            alert(`Error al ${editingUserId ? 'editar' : 'crear'} usuario`);
        }
    };

    const handleDelete = async (id: string) => {
        if (id === currentUser?.id) {
            alert("No puedes eliminar tu propio usuario");
            return;
        }
        if (confirm('¿Eliminar usuario? Esta acción no se puede deshacer.')) {
            await deleteDoc(doc(db, 'users', id));
        }
    };

    const openModal = (user?: User) => {
        if (user) {
            setFormData({
                name: user.name,
                pin: '',
                role: user.role as any,
                restaurantId: user.restaurantId,
            });
            setEditingUserId(user.id);
        } else {
            setFormData({
                name: '',
                pin: '',
                role: 'waiter',
                restaurantId: filterBranch !== 'all' ? filterBranch : (currentUser?.restaurantId || ''),
            });
            setEditingUserId(null);
        }
        setIsModalOpen(true);
    };

    const closeModal = () => {
        setIsModalOpen(false);
        setEditingUserId(null);
    };

    const getRoleBadge = (role: string) => {
        switch (role) {
            case 'admin': return <Badge variant="info">Administrador</Badge>;
            case 'caja': return <Badge variant="info" style={{ backgroundColor: '#8b5cf6', color: 'white' }}>Cajero</Badge>;
            case 'chef': return <Badge variant="warning">Cocinero</Badge>;
            case 'shift_manager': return <Badge variant="success">Encargado de Turno</Badge>;
            default: return <Badge variant="neutral">Mozo</Badge>;
        }
    };

    const getRoleBorderColor = (role: string) => {
        switch (role) {
            case 'admin': return 'var(--primary-color)';
            case 'caja': return '#8b5cf6';
            case 'chef': return 'var(--warning-color)';
            case 'shift_manager': return 'var(--success-color)';
            default: return '#ccc';
        }
    };

    return (
        <div>
            {/* Header with branch summary (multi-branch only) */}
            {isMultiBranch && (
                <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(160px, 1fr))', gap: '1rem', marginBottom: '1.5rem' }}>
                    {allRestaurantIds.map(branchId => {
                        const branchUsers = usersByBranch[branchId] || [];
                        const name = getBranchName(branchId);
                        const isActive = filterBranch === branchId;
                        return (
                            <button
                                key={branchId}
                                onClick={() => setFilterBranch(isActive ? 'all' : branchId)}
                                style={{
                                    padding: '1rem', borderRadius: '10px', cursor: 'pointer',
                                    border: `2px solid ${isActive ? 'var(--primary-color)' : 'var(--divider-color)'}`,
                                    background: isActive ? 'rgba(37, 99, 235, 0.05)' : 'var(--surface-color)',
                                    textAlign: 'center', fontFamily: 'inherit', display: 'flex',
                                    flexDirection: 'column', alignItems: 'center', gap: '0.5rem',
                                    transition: 'all 0.15s ease',
                                }}
                            >
                                <Building2 size={18} color={isActive ? 'var(--primary-color)' : 'var(--text-secondary)'} />
                                <div style={{ fontWeight: 600, fontSize: '0.85rem', color: isActive ? 'var(--primary-color)' : 'var(--text-primary)' }}>
                                    {name}
                                </div>
                                <div style={{ fontSize: '1.25rem', fontWeight: 700, color: isActive ? 'var(--primary-color)' : 'var(--text-primary)' }}>
                                    {branchUsers.length} <span style={{ fontSize: '0.75rem', fontWeight: 400, color: 'var(--text-secondary)' }}>usuarios</span>
                                </div>
                            </button>
                        );
                    })}
                </div>
