import { useState, useEffect } from 'react';
import { db } from '@/services/firebase/config';
import { collection, query, where, onSnapshot } from 'firebase/firestore';
import type { Product, Category } from '@/types';

/**
 * Public hook — no authentication required.
 * Fetches available products and categories for a given restaurant.
 */
export function usePublicMenu(restaurantId: string | undefined) {
    const [products, setProducts] = useState<Product[]>([]);
    const [categories, setCategories] = useState<Category[]>([]);
    const [isLoading, setIsLoading] = useState(true);

    useEffect(() => {
        if (!restaurantId) {
            setIsLoading(false);
            return;
        }

        setIsLoading(true);

        const pQuery = query(
            collection(db, 'products'),
            where('restaurantId', '==', restaurantId),
            where('available', '==', true)
        );

        const cQuery = query(
            collection(db, 'categories'),
            where('restaurantId', '==', restaurantId)
        );

        let productsLoaded = false;
        let categoriesLoaded = false;

        const checkDone = () => {
            if (productsLoaded && categoriesLoaded) {
                setIsLoading(false);
            }
        };

        const unsubProducts = onSnapshot(pQuery, (snap) => {
            const data = snap.docs.map(d => ({ id: d.id, ...d.data() } as Product));
            setProducts(data);
            productsLoaded = true;
            checkDone();
        });

        const unsubCategories = onSnapshot(cQuery, (snap) => {
            const data = snap.docs.map(d => ({ id: d.id, ...d.data() } as Category));
            // Sort by sortOrder first, then alphabetically as fallback
            const sorted = data.sort((a, b) => {
                if (a.sortOrder !== undefined && b.sortOrder !== undefined) {
                    return a.sortOrder - b.sortOrder;
                }
                if (a.sortOrder !== undefined) return -1;
                if (b.sortOrder !== undefined) return 1;
                return a.name.localeCompare(b.name);
            });
            setCategories(sorted);
            categoriesLoaded = true;
            checkDone();
        });

        return () => {
            unsubProducts();
            unsubCategories();
        };
    }, [restaurantId]);

    return { products, categories, isLoading };
}

import React, { createContext, useContext, useState } from 'react';
import { hashPin } from '@/utils/crypto';

interface SuperAdminAuthContextType {
    isAuthenticated: boolean;
    login: (pin: string) => Promise<boolean>;
    logout: () => void;
}

const SuperAdminAuthContext = createContext<SuperAdminAuthContextType | undefined>(undefined);

const MASTER_PIN = import.meta.env.VITE_SUPERADMIN_PIN || import.meta.env.VITE_SUPERADMIN_KEY || 'admin123';
const SESSION_KEY = 'sa_auth_session';

export function SuperAdminAuthProvider({ children }: { children: React.ReactNode }) {
    const [isAuthenticated, setIsAuthenticated] = useState<boolean>(() => {
        // Obfuscated check instead of plain string
        const session = sessionStorage.getItem(SESSION_KEY);
        try {
            if (session) {
                const dec = atob(session);
                return dec === `SUPER_ADMIN_VALID_${new Date().toISOString().split('T')[0]}`;
            }
        } catch {
            return false;
        }
        return false;
    });

    const login = async (pin: string) => {
        const hashedInput = await hashPin(pin);
        const hashedMaster = await hashPin(MASTER_PIN);
        const isValid = hashedInput === hashedMaster;

        if (isValid) {
            setIsAuthenticated(true);
            sessionStorage.setItem(SESSION_KEY, btoa(`SUPER_ADMIN_VALID_${new Date().toISOString().split('T')[0]}`));
        }
        return isValid;
    };

    const logout = () => {
        setIsAuthenticated(false);
        sessionStorage.removeItem(SESSION_KEY);
    };

    return (
        <SuperAdminAuthContext.Provider value={{ isAuthenticated, login, logout }}>
            {children}
        </SuperAdminAuthContext.Provider>
    );
}

export function useSuperAdminAuth() {
    const context = useContext(SuperAdminAuthContext);
    if (!context) {
        throw new Error("useSuperAdminAuth must be used within a SuperAdminAuthProvider");
    }
    return context;
}

import { useState, useEffect, useMemo } from 'react';
import { collection, getDocs, updateDoc, doc, deleteDoc } from 'firebase/firestore';
import { db } from '@/services/firebase/config';
import type { Restaurant } from '@/types';

export function useSuperAdminData() {
    const [restaurants, setRestaurants] = useState<Restaurant[]>([]);
    const [loading, setLoading] = useState(true);
    const [searchQuery, setSearchQuery] = useState('');
    const [statusFilter, setStatusFilter] = useState<'all' | 'active' | 'inactive' | 'premium' | 'basic'>('all');

    const fetchRestaurants = async () => {
        try {
            setLoading(true);
            const querySnapshot = await getDocs(collection(db, 'restaurants'));
            const data: Restaurant[] = [];
            querySnapshot.forEach((docSnap) => {
                data.push({ id: docSnap.id, ...docSnap.data() } as Restaurant);
            });
            // Sort by created date descending (newest first)
            data.sort((a, b) => {
                const dateA = (a.createdAt as any)?.seconds || 0;
                const dateB = (b.createdAt as any)?.seconds || 0;
                return dateB - dateA;
            });
            setRestaurants(data);
        } catch (error) {
            console.error("Error fetching restaurants:", error);
            alert("Error al cargar restaurantes");
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => {
        fetchRestaurants();
    }, []);

    const toggleActive = async (id: string, currentStatus: boolean) => {
        try {
            // Optimistic Update
            setRestaurants(prev => prev.map(r => r.id === id ? { ...r, active: !currentStatus } : r));
            await updateDoc(doc(db, 'restaurants', id), { active: !currentStatus });
        } catch (error) {
            console.error("Error updating status:", error);
            alert("Error al actualizar estado");
            // Revert on error
            setRestaurants(prev => prev.map(r => r.id === id ? { ...r, active: currentStatus } : r));
        }
    };

    const toggleDigitalMenu = async (id: string, currentStatus: boolean) => {
        try {
            setRestaurants(prev => prev.map(r => r.id === id ? { ...r, features: { ...r.features, digitalMenu: !currentStatus } } : r));
            await updateDoc(doc(db, 'restaurants', id), { 'features.digitalMenu': !currentStatus });
        } catch (error) {
            console.error("Error toggling digital menu:", error);
            alert("Error al cambiar menú digital");
            setRestaurants(prev => prev.map(r => r.id === id ? { ...r, features: { ...r.features, digitalMenu: currentStatus } } : r));
        }
    };

    const changePlan = async (id: string, currentPlan: 'basic' | 'premium', name: string) => {
        const newPlan = currentPlan === 'premium' ? 'basic' : 'premium';
        const action = newPlan === 'premium' ? 'SUBIR a Premium' : 'BAJAR a Basic';

        if (!window.confirm(`¿Confirmas ${action} para "${name}"?${newPlan === 'basic' ? '\n\n⚠️ El Menú Digital será desactivado automáticamente.' : ''}`)) return;

        try {
            const updates: Record<string, unknown> = { plan: newPlan };
            if (newPlan === 'basic') updates['features.digitalMenu'] = false;
            else updates['features.digitalMenu'] = true;

            // Optimistic update
            setRestaurants(prev => prev.map(r => r.id === id ? {
                ...r, plan: newPlan, features: { ...r.features, digitalMenu: newPlan === 'premium' }
            } : r));

            await updateDoc(doc(db, 'restaurants', id), updates);
            // alert(`Plan actualizado a ${newPlan.toUpperCase()} para "${name}".`);
        } catch (error) {
            console.error("Error changing plan:", error);
            alert("Error al cambiar el plan");
            fetchRestaurants(); // Revert completely
        }
    };

    const renewSubscription = async (id: string) => {
        const daysStr = window.prompt("¿Cuántos días quieres agregar a la suscripción?", "30");
        if (!daysStr) return;
        const days = parseInt(daysStr, 10);
        if (isNaN(days) || days <= 0) {
            alert("Días inválidos.");
            return;
        }

        try {
            const currentDoc = restaurants.find(r => r.id === id);
            if (!currentDoc) return;

            let newDate = new Date(); // From today
            if (currentDoc.subscriptionEndsAt) {
                const currentEnd = new Date((currentDoc.subscriptionEndsAt as any).seconds ? (currentDoc.subscriptionEndsAt as any).seconds * 1000 : currentDoc.subscriptionEndsAt);
                if (currentEnd > new Date()) {
                    newDate = currentEnd; // Add to existing time if not expired
                }
            }
            newDate.setDate(newDate.getDate() + days);

            // Optimistic
            setRestaurants(prev => prev.map(r => r.id === id ? { ...r, subscriptionEndsAt: newDate as any } : r));

            await updateDoc(doc(db, 'restaurants', id), {
                subscriptionEndsAt: newDate
            });
            alert(`Suscripción renovada por ${days} días.`);
        } catch (error) {
            console.error("Error renewing:", error);
            alert("Error al renovar suscripción");
            fetchRestaurants();
        }
    };

    const handleDelete = async (id: string, name: string) => {
        if (!window.confirm(`¿ESTÁS SEGURO de eliminar el restaurante "${name}"? Esta acción borra el documento de Firestore de forma permanente.`)) return;

        try {
            setRestaurants(prev => prev.filter(r => r.id !== id));
            await deleteDoc(doc(db, 'restaurants', id));
        } catch (error) {
            console.error("Error deleting:", error);
            alert("Error al eliminar restaurante");
            fetchRestaurants();
        }
    };

    const filteredRestaurants = useMemo(() => {
        let result = restaurants;

        // Apply Status Filter
        if (statusFilter === 'active') result = result.filter(r => r.active);
        if (statusFilter === 'inactive') result = result.filter(r => !r.active);
        if (statusFilter === 'premium') result = result.filter(r => r.plan === 'premium');
        if (statusFilter === 'basic') result = result.filter(r => r.plan === 'basic');

        // Apply Search
        if (searchQuery.trim()) {
            const query = searchQuery.toLowerCase();
            result = result.filter(r =>
                r.name.toLowerCase().includes(query) ||
                r.id.toLowerCase().includes(query)
            );
        }

        return result;
    }, [restaurants, statusFilter, searchQuery]);


    return {
        restaurants: filteredRestaurants,
        totalRestaurants: restaurants.length,
        loading,
        searchQuery,
        setSearchQuery,
        statusFilter,
        setStatusFilter,
        toggleActive,
        toggleDigitalMenu,
        changePlan,
        renewSubscription,
        handleDelete
    };
}

import { useState, useRef } from 'react';
import { useNavigate } from 'react-router-dom';
import { Card, Button, Badge, Input } from '@/components/shared';
import { useAuth } from '@/hooks/useAuth';
import { usePettyCash } from '@/hooks/usePettyCash';
import {
    ArrowLeft, Wallet, Plus, Clock, CheckCircle, XCircle, AlertTriangle,
    Eye, Camera, Send, X, ShieldCheck, FileText, TrendingDown,
    ChevronDown, ChevronUp, Image as ImageIcon
} from 'lucide-react';
import { PettyCashExpenseStatus as PCStatus, PettyCashCategory, UserRole } from '@/types';
import type { PettyCashExpense, PettyCashCategory as PCCategoryType } from '@/types';
import { formatPeruDisplay } from '@/utils/dateUtils';

// ── Helpers ──────────────────────────────────────────────────────────────────
const STATUS_CONFIG: Record<string, { label: string; color: string; bg: string; icon: React.ReactNode }> = {
    [PCStatus.PENDING]: { label: 'Pendiente', color: '#f59e0b', bg: 'rgba(245,158,11,0.10)', icon: <Clock size={14} /> },
    [PCStatus.AUTO_APPROVED]: { label: 'Auto-Aprobado', color: '#10b981', bg: 'rgba(16,185,129,0.10)', icon: <ShieldCheck size={14} /> },
    [PCStatus.APPROVED]: { label: 'Aprobado', color: '#22c55e', bg: 'rgba(34,197,94,0.10)', icon: <CheckCircle size={14} /> },
    [PCStatus.REJECTED]: { label: 'Rechazado', color: '#ef4444', bg: 'rgba(239,68,68,0.10)', icon: <XCircle size={14} /> },
    [PCStatus.OBSERVED]: { label: 'Observado', color: '#8b5cf6', bg: 'rgba(139,92,246,0.10)', icon: <Eye size={14} /> },
};

const CATEGORY_ICONS: Record<string, string> = {
    'Ingredientes': '🥬',
    'Gas': '🔥',
    'Limpieza': '🧹',
    'Transporte': '🚗',
    'Insumos': '📦',
    'Otro': '📋',
};

export function CajaChicaPage() {
    const navigate = useNavigate();
    const { user } = useAuth();
    const {
        expenses, isLoading, summary, config, pettyCashBalance, currentSession,
        requestExpense, approveExpense, rejectExpense, addObservation,
        canRegisterDirectExpense, canApproveExpenses, canViewAllExpenses,
        hasPendingExpenses, isSessionOpen,
    } = usePettyCash();

    // ── Modal states ─────────────────────────────────────────────────────────
    const [showExpenseModal, setShowExpenseModal] = useState(false);
    const [showRejectModal, setShowRejectModal] = useState<string | null>(null);
    const [showObsModal, setShowObsModal] = useState<string | null>(null);
    const [showReceiptImage, setShowReceiptImage] = useState<string | null>(null);
    const [expandedExpense, setExpandedExpense] = useState<string | null>(null);

    // Expense form
    const [formData, setFormData] = useState({ amount: '', description: '', category: PettyCashCategory.INGREDIENTS as PCCategoryType });
    const [receiptFile, setReceiptFile] = useState<File | null>(null);
    const [receiptPreview, setReceiptPreview] = useState<string>('');
    const [isSubmitting, setIsSubmitting] = useState(false);
    const [rejectReason, setRejectReason] = useState('');
    const [obsNote, setObsNote] = useState('');
    const fileInputRef = useRef<HTMLInputElement>(null);

    // ── Loading state ────────────────────────────────────────────────────────
    if (isLoading) {
        return (
            <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', minHeight: '60vh', gap: '1rem' }}>
                <div style={{ width: '48px', height: '48px', border: '4px solid var(--border-color)', borderTopColor: 'var(--primary-color)', borderRadius: '50%', animation: 'spin 0.8s linear infinite' }} />
                <p style={{ color: 'var(--text-secondary)', fontWeight: '600' }}>Cargando Caja Chica...</p>
            </div>
        );
    }

    // ── No session open ──────────────────────────────────────────────────────
    if (!currentSession) {
        return (
            <div className="container mt-md" style={{ maxWidth: '480px' }}>
                <Button variant="ghost" onClick={() => navigate(-1)} style={{ display: 'inline-flex', alignItems: 'center', gap: '0.4rem', marginBottom: '1.5rem', fontSize: '0.9rem' }}>
                    <ArrowLeft size={16} /> Volver
                </Button>
                <Card style={{ padding: '2.5rem 2rem', textAlign: 'center' }}>
                    <div style={{
                        background: 'linear-gradient(135deg, rgba(245,158,11,0.12), rgba(245,158,11,0.06))',
                        width: '80px', height: '80px', borderRadius: '50%',
                        display: 'flex', alignItems: 'center', justifyContent: 'center',
                        margin: '0 auto 1.5rem', border: '2px solid rgba(245,158,11,0.15)'
                    }}>
                        <Wallet size={36} color="#f59e0b" />
                    </div>
                    <h1 style={{ fontSize: '1.5rem', fontWeight: '800', marginBottom: '0.5rem' }}>Caja Chica</h1>
                    <p style={{ color: 'var(--text-secondary)', fontSize: '0.95rem', lineHeight: '1.5' }}>
                        No hay una sesión de caja abierta hoy.<br />
                        Primero debes <strong>abrir la caja</strong> desde el Cierre de Caja.
                    </p>
                    <Button fullWidth onClick={() => navigate(-1)} style={{ marginTop: '1.5rem' }}>
                        Ir a Cierre de Caja
                    </Button>
                </Card>
            </div>
        );
    }

    // ── File handling ────────────────────────────────────────────────────────
    const handleFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (file) {
            setReceiptFile(file);
            const reader = new FileReader();
            reader.onload = (ev) => setReceiptPreview(ev.target?.result as string);
            reader.readAsDataURL(file);
        }
    };

    const clearReceipt = () => {
        setReceiptFile(null);
        setReceiptPreview('');
        if (fileInputRef.current) fileInputRef.current.value = '';
    };

    // ── Submit expense ───────────────────────────────────────────────────────
    const handleSubmitExpense = async (e: React.FormEvent) => {
        e.preventDefault();
        const amount = parseFloat(formData.amount);
        if (isNaN(amount) || amount <= 0 || !formData.description.trim()) return;

        setIsSubmitting(true);
        try {
            const result = await requestExpense({
                amount,
                description: formData.description.trim(),
                category: formData.category,
                receiptFile: receiptFile || undefined,
            });

            setShowExpenseModal(false);
            setFormData({ amount: '', description: '', category: PettyCashCategory.INGREDIENTS });
            clearReceipt();

            if (result.autoApproved) {
                alert('✅ Gasto registrado y aprobado automáticamente.');
            } else {
                alert('📋 Solicitud de gasto registrada. Pendiente de aprobación del admin.');
            }
        } catch (error) {
            console.error('Error registrando gasto:', error);
            alert('❌ Error al registrar el gasto.');
        } finally {
            setIsSubmitting(false);
        }
    };

    // ── Admin actions ────────────────────────────────────────────────────────
    const handleApprove = async (id: string) => {
        if (!confirm('¿Aprobar este gasto?')) return;
        try {
            await approveExpense(id);
        } catch (error) {
            alert('❌ Error al aprobar.');
        }
    };

    const handleReject = async () => {
        if (!showRejectModal || !rejectReason.trim()) return;
        try {
            await rejectExpense(showRejectModal, rejectReason.trim());
            setShowRejectModal(null);
            setRejectReason('');
        } catch (error) {
            alert('❌ Error al rechazar.');
        }
    };

    const handleObservation = async () => {
        if (!showObsModal || !obsNote.trim()) return;
        try {
            await addObservation(showObsModal, obsNote.trim());
            setShowObsModal(null);
            setObsNote('');
        } catch (error) {
            alert('❌ Error al agregar observación.');
        }
    };

    // Filter expenses for non-admin roles
    const visibleExpenses = canViewAllExpenses
        ? expenses
        : expenses.filter(e => e.requestedBy === user?.id);

    // Balance health indicator
    const openingBalance = currentSession?.openingBalance || 0;
    const balancePercent = openingBalance > 0 ? (pettyCashBalance / openingBalance) * 100 : 100;
    const balanceHealth = balancePercent > 50 ? 'healthy' : balancePercent > 20 ? 'warning' : 'critical';
    const balanceColors = {
        healthy: { color: '#10b981', bg: 'rgba(16,185,129,0.08)', border: 'rgba(16,185,129,0.2)' },
        warning: { color: '#f59e0b', bg: 'rgba(245,158,11,0.08)', border: 'rgba(245,158,11,0.2)' },
        critical: { color: '#ef4444', bg: 'rgba(239,68,68,0.08)', border: 'rgba(239,68,68,0.2)' },
    }[balanceHealth];

    const isClosed = currentSession?.status === 'closed';

    // ── MAIN RENDER ──────────────────────────────────────────────────────────
    return (
        <div className="container mt-md">
            {/* ── HEADER ── */}
            <header style={{
                marginBottom: '1.5rem', paddingBottom: '1.25rem',
                borderBottom: '1px solid var(--divider-color)'
            }}>
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', gap: '0.5rem', flexWrap: 'wrap', marginBottom: '0.75rem' }}>
                    <Button variant="ghost" onClick={() => navigate(-1)} size="sm"
                        style={{ display: 'inline-flex', alignItems: 'center', gap: '0.35rem' }}>
                        <ArrowLeft size={16} /> Volver
                    </Button>
                    {!isClosed && isSessionOpen && (
                        <button
                            onClick={() => setShowExpenseModal(true)}
                            style={{
                                display: 'flex', alignItems: 'center', gap: '0.4rem',
                                padding: '0.55rem 1rem', borderRadius: 'var(--radius-md)',
                                background: 'linear-gradient(135deg, #2563eb, #1d4ed8)',
                                color: 'white', border: 'none', cursor: 'pointer',
                                fontWeight: '700', fontSize: '0.85rem',
                                boxShadow: '0 4px 12px rgba(37,99,235,0.25)',
                                transition: 'all 0.2s ease',
                            }}
                        >
                            <Plus size={16} />
                            <span className="btn-label">
                                {canRegisterDirectExpense ? 'Registrar Gasto' : 'Solicitar Gasto'}
                            </span>
                        </button>
                    )}
                </div>
                <div>
                    <h1 style={{ margin: 0, fontSize: 'clamp(1.3rem, 4vw, 1.8rem)', fontWeight: '900', lineHeight: 1.2, display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
                        <Wallet size={28} style={{ color: 'var(--primary-color)' }} />
                        Caja Chica
                    </h1>
                    <p style={{ margin: '0.25rem 0 0', color: 'var(--text-secondary)', fontSize: '0.9rem' }}>
                        {formatPeruDisplay(new Date())} · <span style={{ fontWeight: '600', color: 'var(--text-primary)' }}>{user?.name}</span>
                        <Badge variant="neutral" style={{ marginLeft: '0.5rem', fontSize: '0.7rem', textTransform: 'capitalize' }}>
                            {user?.role === UserRole.SHIFT_MANAGER ? 'Encargado' : user?.role}
                        </Badge>
                    </p>
                </div>
            </header>

            {/* ── SESSION CLOSED BANNER ── */}
            {isClosed && (
                <div style={{
                    background: 'var(--surface-color)', color: 'var(--success-color)',
                    padding: '1rem 1.25rem', borderRadius: 'var(--radius-lg)',
                    marginBottom: '1.25rem', border: '1px solid var(--border-color)',
                    borderLeft: '5px solid var(--success-color)',
                    display: 'flex', alignItems: 'center', gap: '0.75rem',
                    boxShadow: 'var(--shadow-sm)'
                }}>
                    <CheckCircle size={20} style={{ flexShrink: 0 }} />
                    <span style={{ fontWeight: '600', fontSize: '0.9rem' }}>
                        La caja del día fue cerrada. Los movimientos son de solo lectura.
                    </span>
                </div>
            )}

            {/* ── PENDING ALERT ── */}
            {canApproveExpenses && hasPendingExpenses && (
                <div style={{
                    background: 'rgba(245,158,11,0.08)', color: '#b45309',
                    padding: '1rem 1.25rem', borderRadius: 'var(--radius-lg)',
                    marginBottom: '1.25rem', border: '1px solid rgba(245,158,11,0.2)',
                    borderLeft: '5px solid #f59e0b',
                    display: 'flex', alignItems: 'center', gap: '0.75rem',
                    boxShadow: 'var(--shadow-sm)'
                }}>
                    <AlertTriangle size={20} style={{ flexShrink: 0 }} />
                    <span style={{ fontWeight: '600', fontSize: '0.9rem' }}>
                        Tienes <strong>{summary.countPending}</strong> solicitud{summary.countPending !== 1 ? 'es' : ''} pendiente{summary.countPending !== 1 ? 's' : ''} de aprobación (S/ {summary.totalPending.toFixed(2)}).
                    </span>
                </div>
            )}

            {/* ── METRICS GRID ── */}
            <div style={{
                display: 'grid',
                gridTemplateColumns: 'repeat(auto-fit, minmax(min(100%, 260px), 1fr))',
                gap: '1rem', marginBottom: '2rem'
            }}>
                {/* Saldo Card */}
                <Card style={{
                    padding: '1.5rem',
                    borderTop: `4px solid ${balanceColors.color}`,
                    borderRadius: 'var(--radius-xl)',
                    boxShadow: 'var(--shadow-md)',
                    background: balanceColors.bg,
                }}>
                    <div style={{ display: 'flex', alignItems: 'center', gap: '0.6rem', marginBottom: '0.75rem' }}>
                        <div style={{
                            width: '36px', height: '36px', borderRadius: 'var(--radius-md)',
                            background: `${balanceColors.color}20`,
                            display: 'flex', alignItems: 'center', justifyContent: 'center', flexShrink: 0
                        }}>
                            <Wallet size={20} style={{ color: balanceColors.color }} />
                        </div>
                        <h3 style={{ margin: 0, fontWeight: '800', color: 'var(--text-secondary)', textTransform: 'uppercase', letterSpacing: '0.05em', fontSize: '0.8rem' }}>
                            Saldo Disponible
                        </h3>
                    </div>
                    <div style={{
                        fontSize: 'clamp(2rem, 7vw, 2.8rem)', fontWeight: '900',
                        color: balanceColors.color, letterSpacing: '-0.03em', lineHeight: '1.1',
                        marginBottom: '0.75rem'
                    }}>
                        S/ {pettyCashBalance.toFixed(2)}
                    </div>
                    {/* Mini balance bar */}
                    <div style={{ background: 'rgba(0,0,0,0.08)', height: '6px', borderRadius: '3px', overflow: 'hidden', marginBottom: '0.5rem' }}>
                        <div style={{
                            width: `${Math.max(0, Math.min(100, balancePercent))}%`,
                            height: '100%', borderRadius: '3px',
                            background: balanceColors.color,
                            transition: 'width 0.5s ease',
                        }} />
                    </div>
                    <div style={{ fontSize: '0.78rem', color: 'var(--text-secondary)' }}>
                        Fondo inicial: S/ {openingBalance.toFixed(2)}
                    </div>
                </Card>

                {/* Gastos del Día */}
                <Card style={{
                    padding: '1.5rem', borderRadius: 'var(--radius-xl)',
                    boxShadow: 'var(--shadow-md)',
                }}>
                    <div style={{ display: 'flex', alignItems: 'center', gap: '0.6rem', marginBottom: '1rem' }}>
                        <div style={{
                            width: '36px', height: '36px', borderRadius: 'var(--radius-md)',
                            background: 'rgba(239,68,68,0.1)',
                            display: 'flex', alignItems: 'center', justifyContent: 'center', flexShrink: 0
                        }}>
                            <TrendingDown size={18} style={{ color: 'var(--danger-color)' }} />
                        </div>
                        <h3 style={{ margin: 0, fontWeight: '800', fontSize: '0.9rem', color: 'var(--text-primary)' }}>Resumen del Día</h3>
                    </div>
                    <div style={{ display: 'flex', flexDirection: 'column', gap: '0.5rem' }}>
                        <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: '0.88rem', color: 'var(--success-color)' }}>
                            <span style={{ display: 'flex', alignItems: 'center', gap: '0.3rem' }}>
                                <CheckCircle size={14} /> Aprobados ({summary.countApproved})
                            </span>
                            <strong>S/ {summary.totalApproved.toFixed(2)}</strong>
                        </div>
                        <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: '0.88rem', color: '#f59e0b' }}>
                            <span style={{ display: 'flex', alignItems: 'center', gap: '0.3rem' }}>
                                <Clock size={14} /> Pendientes ({summary.countPending})
                            </span>
                            <strong>S/ {summary.totalPending.toFixed(2)}</strong>
                        </div>
                        {summary.countRejected > 0 && (
                            <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: '0.88rem', color: 'var(--danger-color)' }}>
                                <span style={{ display: 'flex', alignItems: 'center', gap: '0.3rem' }}>
                                    <XCircle size={14} /> Rechazados ({summary.countRejected})
                                </span>
                                <strong>S/ {summary.totalRejected.toFixed(2)}</strong>
                            </div>
                        )}
                        <div style={{ borderTop: '1px dashed var(--divider-color)', paddingTop: '0.5rem', marginTop: '0.25rem', display: 'flex', justifyContent: 'space-between', fontSize: '0.85rem' }}>
                            <span style={{ color: 'var(--text-secondary)' }}>Tu gasto hoy</span>
                            <strong style={{ color: 'var(--text-primary)' }}>S/ {summary.userDailyTotal.toFixed(2)} / {config.maxDailyPerUser.toFixed(2)}</strong>
                        </div>
                    </div>
                </Card>

                {/* Reglas Card */}
                <Card style={{ padding: '1.5rem', borderRadius: 'var(--radius-xl)', boxShadow: 'var(--shadow-md)' }}>
                    <div style={{ display: 'flex', alignItems: 'center', gap: '0.6rem', marginBottom: '1rem' }}>
                        <div style={{
                            width: '36px', height: '36px', borderRadius: 'var(--radius-md)',
                            background: 'rgba(139,92,246,0.1)',
                            display: 'flex', alignItems: 'center', justifyContent: 'center', flexShrink: 0
                        }}>
                            <ShieldCheck size={18} style={{ color: '#8b5cf6' }} />
                        </div>
                        <h3 style={{ margin: 0, fontWeight: '800', fontSize: '0.9rem', color: 'var(--text-primary)' }}>Reglas Automáticas</h3>
                    </div>
                    <div style={{ display: 'flex', flexDirection: 'column', gap: '0.6rem', fontSize: '0.85rem' }}>
                        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                            <span style={{ color: 'var(--text-secondary)' }}>Máx. por gasto</span>
                            <Badge variant="neutral" style={{ fontWeight: '800' }}>S/ {config.maxPerExpense.toFixed(2)}</Badge>
                        </div>
                        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                            <span style={{ color: 'var(--text-secondary)' }}>Máx. diario/usuario</span>
                            <Badge variant="neutral" style={{ fontWeight: '800' }}>S/ {config.maxDailyPerUser.toFixed(2)}</Badge>
                        </div>
                        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                            <span style={{ color: 'var(--text-secondary)' }}>Auto-aprobación</span>
                            <Badge variant={config.enableAutoApproval ? 'success' : 'error'} style={{ fontWeight: '700' }}>
                                {config.enableAutoApproval ? '✓ Activa' : '✗ Inactiva'}
                            </Badge>
                        </div>
                        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                            <span style={{ color: 'var(--text-secondary)' }}>Comprobante</span>
                            <Badge variant="neutral" style={{ fontWeight: '700' }}>
                                {config.requireReceipt ? 'Obligatorio' : 'Opcional'}
                            </Badge>
                        </div>
                    </div>
                </Card>
            </div>

            {/* ── EXPENSE LIST ── */}
            <Card style={{ padding: 'clamp(1rem, 4vw, 2rem)', borderRadius: 'var(--radius-xl)', boxShadow: 'var(--shadow-lg)' }}>
                <h3 style={{
                    display: 'flex', alignItems: 'center', gap: '0.5rem',
                    marginBottom: '1.25rem', fontSize: '1rem', fontWeight: '800',
                    borderBottom: '1px solid var(--divider-color)', paddingBottom: '0.75rem'
                }}>
                    <FileText size={20} style={{ color: 'var(--primary-color)' }} />
                    Movimientos de Hoy
                    <Badge variant="neutral" style={{ marginLeft: 'auto', fontSize: '0.75rem' }}>
                        {visibleExpenses.length}
                    </Badge>
                </h3>

                {visibleExpenses.length === 0 ? (
                    <div style={{ textAlign: 'center', padding: '3rem 1rem' }}>
                        <div style={{
                            width: '64px', height: '64px', borderRadius: '50%',
                            background: 'rgba(37,99,235,0.08)', display: 'flex',
                            alignItems: 'center', justifyContent: 'center',
                            margin: '0 auto 1rem'
                        }}>
                            <FileText size={28} color="var(--primary-color)" style={{ opacity: 0.5 }} />
                        </div>
                        <p style={{ color: 'var(--text-secondary)', fontSize: '0.95rem', fontWeight: '600', margin: 0 }}>
                            No hay movimientos registrados hoy
                        </p>
                        <p style={{ color: 'var(--text-secondary)', fontSize: '0.82rem', margin: '0.3rem 0 0', opacity: 0.7 }}>
                            Los gastos de caja chica aparecerán aquí
                        </p>
                    </div>
                ) : (
                    <div style={{ display: 'flex', flexDirection: 'column', gap: '0.75rem' }}>
                        {visibleExpenses.map((expense) => (
                            <ExpenseItem
                                key={expense.id}
                                expense={expense}
                                isExpanded={expandedExpense === expense.id}
                                onToggle={() => setExpandedExpense(expandedExpense === expense.id ? null : expense.id)}
                                canApprove={canApproveExpenses}
                                onApprove={() => handleApprove(expense.id)}
                                onReject={() => setShowRejectModal(expense.id)}
                                onObserve={() => setShowObsModal(expense.id)}
                                onViewReceipt={(url) => setShowReceiptImage(url)}
                                isClosed={isClosed}
                            />
                        ))}
                    </div>
                )}
            </Card>

            {/* ── EXPENSE MODAL ── */}
            {showExpenseModal && (
                <ModalOverlay onClose={() => setShowExpenseModal(false)}>
                    <Card style={{ width: '100%', maxWidth: '420px', padding: '2rem' }}>
                        <h3 style={{ marginBottom: '1.5rem', display: 'flex', alignItems: 'center', gap: '0.5rem', fontSize: '1.1rem' }}>
                            <Plus size={22} color="var(--primary-color)" />
                            {canRegisterDirectExpense ? 'Registrar Gasto' : 'Solicitar Gasto'}
                        </h3>
                        <form onSubmit={handleSubmitExpense} style={{ display: 'flex', flexDirection: 'column', gap: '1rem' }}>
                            <Input
                                label="Monto (S/)"
                                type="number"
                                required
                                placeholder="0.00"
                                value={formData.amount}
                                onChange={e => setFormData({ ...formData, amount: e.target.value })}
                            />
                            {/* Auto-approval hint */}
                            {formData.amount && parseFloat(formData.amount) > 0 && (
                                <div style={{
                                    fontSize: '0.78rem', padding: '0.5rem 0.75rem',
                                    borderRadius: 'var(--radius-sm)',
                                    background: parseFloat(formData.amount) <= config.maxPerExpense
                                        ? 'rgba(16,185,129,0.08)' : 'rgba(245,158,11,0.08)',
                                    color: parseFloat(formData.amount) <= config.maxPerExpense
                                        ? '#10b981' : '#f59e0b',
                                    fontWeight: '600',
                                }}>
                                    {parseFloat(formData.amount) <= config.maxPerExpense
                                        ? '✓ Dentro del límite — se aprobará automáticamente'
                                        : '⏳ Excede el límite — requerirá aprobación del admin'
                                    }
                                </div>
                            )}
                            <Input
                                label="Descripción"
                                placeholder="Ej: Compra de gas para cocina"
                                required
                                value={formData.description}
                                onChange={e => setFormData({ ...formData, description: e.target.value })}
                            />
                            <div>
                                <label style={{ display: 'block', fontWeight: '700', fontSize: '0.85rem', marginBottom: '0.4rem', color: 'var(--text-primary)' }}>
                                    Categoría
                                </label>
                                <select
                                    value={formData.category}
                                    onChange={e => setFormData({ ...formData, category: e.target.value as PCCategoryType })}
                                    style={{
                                        width: '100%', padding: '0.65rem 0.75rem',
                                        borderRadius: 'var(--radius-md)',
                                        border: '1px solid var(--border-color)',
                                        background: 'var(--surface-color)',
                                        color: 'var(--text-primary)',
                                        fontSize: '0.9rem', fontWeight: '600',
                                        cursor: 'pointer',
                                    }}
                                >
                                    {Object.values(PettyCashCategory).map(cat => (
                                        <option key={cat} value={cat}>{CATEGORY_ICONS[cat]} {cat}</option>
                                    ))}
                                </select>
                            </div>
                            {/* Receipt upload */}
                            <div>
                                <label style={{ display: 'block', fontWeight: '700', fontSize: '0.85rem', marginBottom: '0.4rem', color: 'var(--text-primary)' }}>
                                    Comprobante {config.requireReceipt ? '(Obligatorio)' : '(Opcional)'}
                                </label>
                                <input
                                    ref={fileInputRef}
                                    type="file"
                                    accept="image/*"
                                    capture="environment"
                                    onChange={handleFileSelect}
                                    style={{ display: 'none' }}
                                />
                                {receiptPreview ? (
                                    <div style={{ position: 'relative', borderRadius: 'var(--radius-md)', overflow: 'hidden', border: '1px solid var(--border-color)' }}>
                                        <img src={receiptPreview} alt="Comprobante" style={{ width: '100%', maxHeight: '180px', objectFit: 'cover' }} />
                                        <button
                                            type="button"
                                            onClick={clearReceipt}
                                            style={{
                                                position: 'absolute', top: '0.5rem', right: '0.5rem',
                                                width: '28px', height: '28px', borderRadius: '50%',
                                                background: 'rgba(0,0,0,0.6)', color: 'white',
                                                border: 'none', cursor: 'pointer',
                                                display: 'flex', alignItems: 'center', justifyContent: 'center',
                                            }}
                                        >
                                            <X size={14} />
                                        </button>
                                    </div>
                                ) : (
                                    <button
                                        type="button"
                                        onClick={() => fileInputRef.current?.click()}
                                        style={{
                                            width: '100%', padding: '1.25rem',
                                            border: '2px dashed var(--border-color)',
                                            borderRadius: 'var(--radius-md)',
                                            background: 'var(--background-color)',
                                            cursor: 'pointer', display: 'flex',
                                            flexDirection: 'column', alignItems: 'center',
                                            gap: '0.4rem', color: 'var(--text-secondary)',
                                            transition: 'all 0.2s',
                                        }}
                                    >
                                        <Camera size={24} style={{ opacity: 0.5 }} />
                                        <span style={{ fontSize: '0.82rem', fontWeight: '600' }}>
                                            Tomar foto o seleccionar imagen
                                        </span>
                                    </button>
                                )}
                            </div>
                            <div style={{ display: 'flex', gap: '0.75rem', marginTop: '0.5rem' }}>
                                <Button type="button" variant="ghost" onClick={() => setShowExpenseModal(false)} style={{ flex: 1 }}>
                                    Cancelar
                                </Button>
                                <Button
                                    type="submit"
                                    variant="primary"
                                    disabled={isSubmitting || (config.requireReceipt && !receiptFile)}
                                    style={{ flex: 1, display: 'flex', alignItems: 'center', justifyContent: 'center', gap: '0.4rem' }}
                                >
                                    {isSubmitting ? 'Enviando...' : <><Send size={16} /> Enviar</>}
                                </Button>
                            </div>
                        </form>
                    </Card>
                </ModalOverlay>
            )}

            {/* ── REJECT MODAL ── */}
            {showRejectModal && (
                <ModalOverlay onClose={() => { setShowRejectModal(null); setRejectReason(''); }}>
                    <Card style={{ width: '100%', maxWidth: '380px', padding: '2rem' }}>
                        <h3 style={{ marginBottom: '1rem', display: 'flex', alignItems: 'center', gap: '0.5rem', fontSize: '1.05rem' }}>
                            <XCircle size={22} color="var(--danger-color)" /> Rechazar Gasto
                        </h3>
                        <Input
                            label="Motivo del rechazo"
                            placeholder="Ej: Gasto no autorizado"
                            required
                            value={rejectReason}
                            onChange={e => setRejectReason(e.target.value)}
                        />
                        <div style={{ display: 'flex', gap: '0.75rem', marginTop: '1rem' }}>
                            <Button variant="ghost" onClick={() => { setShowRejectModal(null); setRejectReason(''); }} style={{ flex: 1 }}>Cancelar</Button>
                            <Button variant="danger" onClick={handleReject} disabled={!rejectReason.trim()} style={{ flex: 1 }}>Rechazar</Button>
                        </div>
                    </Card>
                </ModalOverlay>
            )}

            {/* ── OBSERVATION MODAL ── */}
            {showObsModal && (
                <ModalOverlay onClose={() => { setShowObsModal(null); setObsNote(''); }}>
                    <Card style={{ width: '100%', maxWidth: '380px', padding: '2rem' }}>
                        <h3 style={{ marginBottom: '1rem', display: 'flex', alignItems: 'center', gap: '0.5rem', fontSize: '1.05rem' }}>
                            <Eye size={22} color="#8b5cf6" /> Agregar Observación
                        </h3>
                        <Input
                            label="Nota / Observación"
                            placeholder="Ej: Verificar monto con factura"
                            required
                            value={obsNote}
                            onChange={e => setObsNote(e.target.value)}
                        />
                        <div style={{ display: 'flex', gap: '0.75rem', marginTop: '1rem' }}>
                            <Button variant="ghost" onClick={() => { setShowObsModal(null); setObsNote(''); }} style={{ flex: 1 }}>Cancelar</Button>
                            <Button variant="primary" onClick={handleObservation} disabled={!obsNote.trim()} style={{ flex: 1 }}>Guardar</Button>
                        </div>
                    </Card>
                </ModalOverlay>
            )}

            {/* ── RECEIPT IMAGE VIEWER ── */}
            {showReceiptImage && (
                <ModalOverlay onClose={() => setShowReceiptImage(null)}>
                    <div style={{ maxWidth: '90vw', maxHeight: '85vh', position: 'relative' }}>
                        <img
                            src={showReceiptImage}
                            alt="Comprobante"
                            style={{ maxWidth: '100%', maxHeight: '80vh', borderRadius: 'var(--radius-lg)', boxShadow: 'var(--shadow-lg)' }}
                        />
                        <button
                            onClick={() => setShowReceiptImage(null)}
                            style={{
                                position: 'absolute', top: '-12px', right: '-12px',
                                width: '36px', height: '36px', borderRadius: '50%',
                                background: 'var(--danger-color)', color: 'white',
                                border: 'none', cursor: 'pointer',
                                display: 'flex', alignItems: 'center', justifyContent: 'center',
                                boxShadow: 'var(--shadow-md)',
                            }}
                        >
                            <X size={18} />
                        </button>
                    </div>
                </ModalOverlay>
            )}

            {/* ── Responsive CSS ── */}
            <style>{`
                @media (max-width: 480px) {
                    .btn-label { display: none; }
                }
                @keyframes spin {
                    to { transform: rotate(360deg); }
                }
            `}</style>
        </div>
    );
}

// ── Sub-Components ───────────────────────────────────────────────────────────

function ModalOverlay({ children, onClose }: { children: React.ReactNode; onClose: () => void }) {
    return (
        <div
            onClick={(e) => { if (e.target === e.currentTarget) onClose(); }}
            style={{
                position: 'fixed', inset: 0,
                background: 'rgba(0,0,0,0.55)',
                backdropFilter: 'blur(4px)',
                display: 'flex', alignItems: 'center', justifyContent: 'center',
                zIndex: 1000, padding: '1rem',
            }}
        >
            {children}
        </div>
    );
}

interface ExpenseItemProps {
    expense: PettyCashExpense;
    isExpanded: boolean;
    onToggle: () => void;
    canApprove: boolean;
    onApprove: () => void;
    onReject: () => void;
    onObserve: () => void;
    onViewReceipt: (url: string) => void;
    isClosed: boolean;
}

function ExpenseItem({ expense, isExpanded, onToggle, canApprove, onApprove, onReject, onObserve, onViewReceipt, isClosed }: ExpenseItemProps) {
    const statusConf = STATUS_CONFIG[expense.status] || STATUS_CONFIG[PCStatus.PENDING];
    const time = new Date(expense.requestedAt).toLocaleTimeString('es-PE', { hour: '2-digit', minute: '2-digit' });
    const isPending = expense.status === PCStatus.PENDING;

    return (
        <div style={{
            border: '1px solid var(--border-color)',
            borderRadius: 'var(--radius-md)',
            overflow: 'hidden',
            transition: 'all 0.2s ease',
            boxShadow: isExpanded ? 'var(--shadow-md)' : 'none',
        }}>
            {/* Main row */}
            <div
                onClick={onToggle}
                style={{
                    display: 'flex', alignItems: 'center', gap: '0.75rem',
                    padding: '0.85rem 1rem', cursor: 'pointer',
                    background: isExpanded ? 'var(--background-color)' : 'transparent',
                    transition: 'background 0.15s',
                }}
            >
                <span style={{ fontSize: '1.3rem', flexShrink: 0 }}>
                    {CATEGORY_ICONS[expense.category] || '📋'}
                </span>
                <div style={{ flex: 1, minWidth: 0 }}>
                    <div style={{ display: 'flex', alignItems: 'center', gap: '0.4rem', flexWrap: 'wrap' }}>
                        <span style={{ fontWeight: '700', fontSize: '0.9rem', color: 'var(--text-primary)' }}>
                            S/ {expense.amount.toFixed(2)}
                        </span>
                        <span style={{
                            display: 'inline-flex', alignItems: 'center', gap: '0.2rem',
                            fontSize: '0.7rem', fontWeight: '700', padding: '0.15rem 0.45rem',
                            borderRadius: '4px', color: statusConf.color, background: statusConf.bg,
                        }}>
                            {statusConf.icon} {statusConf.label}
                        </span>
                    </div>
                    <p style={{
                        margin: '0.15rem 0 0', fontSize: '0.82rem', color: 'var(--text-secondary)',
                        whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis',
                    }}>
                        {expense.description}
                    </p>
                </div>
                <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'flex-end', gap: '0.15rem', flexShrink: 0 }}>
                    <span style={{ fontSize: '0.72rem', color: 'var(--text-secondary)', fontWeight: '600' }}>{time}</span>
                    {isExpanded ? <ChevronUp size={16} color="var(--text-secondary)" /> : <ChevronDown size={16} color="var(--text-secondary)" />}
                </div>
            </div>

            {/* Expanded details */}
            {isExpanded && (
                <div style={{
                    padding: '0.75rem 1rem 1rem',
                    borderTop: '1px solid var(--divider-color)',
                    background: 'var(--background-color)',
                    display: 'flex', flexDirection: 'column', gap: '0.6rem',
                    fontSize: '0.83rem',
                }}>
                    <DetailRow label="Solicitado por" value={`${expense.requestedByName} (${expense.requestedByRole === 'shift_manager' ? 'Encargado' : expense.requestedByRole})`} />
                    <DetailRow label="Categoría" value={`${CATEGORY_ICONS[expense.category] || ''} ${expense.category}`} />
                    <DetailRow label="Descripción" value={expense.description} />
                    {expense.autoApproved && expense.status === PCStatus.AUTO_APPROVED && (
                        <DetailRow label="Aprobación" value="⚡ Automática (dentro de límites)" />
                    )}
                    {expense.approvedByName && (
                        <DetailRow label={expense.status === PCStatus.REJECTED ? 'Rechazado por' : 'Procesado por'} value={expense.approvedByName} />
                    )}
                    {expense.rejectionReason && (
                        <div style={{ background: 'rgba(239,68,68,0.06)', padding: '0.5rem 0.75rem', borderRadius: 'var(--radius-sm)', border: '1px solid rgba(239,68,68,0.15)' }}>
                            <span style={{ fontWeight: '700', color: 'var(--danger-color)', fontSize: '0.78rem' }}>Motivo: </span>
                            <span style={{ color: 'var(--text-primary)' }}>{expense.rejectionReason}</span>
                        </div>
                    )}
                    {expense.observation && (
                        <div style={{ background: 'rgba(139,92,246,0.06)', padding: '0.5rem 0.75rem', borderRadius: 'var(--radius-sm)', border: '1px solid rgba(139,92,246,0.15)' }}>
                            <span style={{ fontWeight: '700', color: '#8b5cf6', fontSize: '0.78rem' }}>Observación: </span>
                            <span style={{ color: 'var(--text-primary)' }}>{expense.observation}</span>
                        </div>
                    )}
                    {expense.receiptUrl && (
                        <button
                            onClick={() => onViewReceipt(expense.receiptUrl!)}
                            style={{
                                display: 'flex', alignItems: 'center', gap: '0.4rem',
                                padding: '0.5rem 0.75rem', borderRadius: 'var(--radius-sm)',
                                background: 'rgba(37,99,235,0.08)', border: '1px solid rgba(37,99,235,0.15)',
                                color: 'var(--primary-color)', cursor: 'pointer',
                                fontWeight: '700', fontSize: '0.82rem',
                            }}
                        >
                            <ImageIcon size={16} /> Ver Comprobante
                        </button>
                    )}
                    {/* Admin actions */}
                    {canApprove && isPending && !isClosed && (
                        <div style={{ display: 'flex', gap: '0.5rem', marginTop: '0.25rem', paddingTop: '0.6rem', borderTop: '1px dashed var(--divider-color)' }}>
                            <button onClick={onApprove} style={actionBtnStyle('#10b981', 'rgba(16,185,129,0.08)')}>
                                <CheckCircle size={14} /> Aprobar
                            </button>
                            <button onClick={onObserve} style={actionBtnStyle('#8b5cf6', 'rgba(139,92,246,0.08)')}>
                                <Eye size={14} /> Observar
                            </button>
                            <button onClick={onReject} style={actionBtnStyle('#ef4444', 'rgba(239,68,68,0.08)')}>
                                <XCircle size={14} /> Rechazar
                            </button>
                        </div>
                    )}
                </div>
            )}
        </div>
    );
}

function DetailRow({ label, value }: { label: string; value: string }) {
    return (
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', gap: '0.5rem' }}>
            <span style={{ color: 'var(--text-secondary)', fontWeight: '600', flexShrink: 0 }}>{label}</span>
            <span style={{ color: 'var(--text-primary)', textAlign: 'right', wordBreak: 'break-word' }}>{value}</span>
        </div>
    );
}

function actionBtnStyle(color: string, bg: string): React.CSSProperties {
    return {
        flex: 1, display: 'flex', alignItems: 'center', justifyContent: 'center',
        gap: '0.3rem', padding: '0.5rem', borderRadius: 'var(--radius-sm)',
        border: `1px solid ${color}22`, background: bg, color,
        fontWeight: '700', fontSize: '0.78rem', cursor: 'pointer',
        transition: 'all 0.15s',
    };
}

import { useState, useEffect } from 'react';
import { parseISO } from 'date-fns';
import { useNavigate, useSearchParams, useParams } from 'react-router-dom';
import { useDailySales } from '@/hooks/useDailySales';
import { useAuth } from '@/hooks/useAuth';
import { useOrders } from '@/hooks/useOrders';
import { useCashSession } from '@/hooks/useCashSession';
import { Card, Button, Badge, Input } from '@/components/shared';
import { Download, ArrowLeft, CheckCircle, AlertTriangle, Check, Lock, DollarSign, CreditCard, User, Wallet, List, ExternalLink } from 'lucide-react';
import { updateDoc, doc, collection, query, where, onSnapshot } from 'firebase/firestore';
import { db } from '@/services/firebase/config';
import { exportDailySalesToExcel } from '@/services/exportExcel';
import type { PettyCashExportItem } from '@/services/exportExcel';
import { getPeruDateString, getPeruNow, formatPeruDisplay } from '@/utils/dateUtils';

export function CierreCajaPage() {
    const navigate = useNavigate();
    const { restaurantSlug } = useParams<{ restaurantSlug: string }>();
    const [searchParams] = useSearchParams();
    const dateParam = searchParams.get('date');
    const targetDate = dateParam ? parseISO(dateParam) : new Date();
    const targetDateStr = getPeruDateString(targetDate);

    const { user } = useAuth();
    const { metrics, orders, isLoading: loadingMetrics } = useDailySales(targetDate);
    const { activeOrders } = useOrders();
    const { currentSession, isLoading: loadingSession, openSession } = useCashSession();
    const restaurantId = user?.restaurantId || '';

    // Petty Cash integration
    const [pettyCashPendingCount, setPettyCashPendingCount] = useState(0);
    const [pettyCashApprovedTotal, setPettyCashApprovedTotal] = useState(0);
    const [pettyCashExpenseItems, setPettyCashExpenseItems] = useState<PettyCashExportItem[]>([]);

    const [isClosing, setIsClosing] = useState(false);
    const [openingBalanceInput, setOpeningBalanceInput] = useState('');

    const [actualCashInput, setActualCashInput] = useState('');

    const isToday = targetDateStr === getPeruDateString();
    const sessionExists = !!currentSession;
    const isClosed = currentSession?.status === 'closed';

    // Listen to petty cash expenses for this date
    useEffect(() => {
        if (!restaurantId || !targetDateStr) return;

        const q = query(
            collection(db, 'pettyCashExpenses'),
            where('restaurantId', '==', restaurantId),
            where('date', '==', targetDateStr)
        );

        const unsubscribe = onSnapshot(q, (snapshot) => {
            let pending = 0;
            let approved = 0;
            const expenseItems: PettyCashExportItem[] = [];
            snapshot.docs.forEach(d => {
                const data = d.data();
                if (data.status === 'pending') pending++;
                if (data.status === 'auto_approved' || data.status === 'approved') {
                    approved += data.amount || 0;
                }
                // Capture all expenses (approved/auto-approved) for Excel export
                if (data.status === 'auto_approved' || data.status === 'approved') {
                    expenseItems.push({
                        category: data.category || 'Otro',
                        description: data.description || '',
                        amount: data.amount || 0,
                        requestedByName: data.requestedByName || 'Desconocido',
                        status: data.status,
                    });
                }
            });
            setPettyCashPendingCount(pending);
            setPettyCashApprovedTotal(approved);
            setPettyCashExpenseItems(expenseItems);
        });

        return () => unsubscribe();
    }, [restaurantId, targetDateStr]);

    if (loadingMetrics || loadingSession) {
        return (
            <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', minHeight: '60vh', gap: '1rem' }}>
                <div style={{ width: '48px', height: '48px', border: '4px solid var(--border-color)', borderTopColor: 'var(--primary-color)', borderRadius: '50%', animation: 'spin 0.8s linear infinite' }} />
                <p style={{ color: 'var(--text-secondary)', fontWeight: '600' }}>Cargando estado financiero...</p>
            </div>
        );
    }

    const hasPendingOrders = activeOrders.length > 0;
    const canClose = !hasPendingOrders && sessionExists && !isClosed;

    const handleCloseBox = async () => {
        if (!canClose || !currentSession?.id) return;

        const actualCash = parseFloat(actualCashInput);
        if (isNaN(actualCash)) {
            alert('Por favor, ingrese el efectivo físico en caja.');
            return;
        }
        if (!confirm('¿Estás seguro de CERRAR CAJA?\nEsta acción es irreversible y bloqueará las ventas del día.')) return;

        setIsClosing(true);
        try {
            const totalCashSales = Object.entries(metrics.salesByPaymentMethod)
                .filter(([method]) => ['cash', 'efectivo'].includes(method.toLowerCase()))
                .reduce((sum, [_, amount]) => sum + amount, 0);
            const expectedCash = (currentSession.openingBalance || 0) + totalCashSales - pettyCashApprovedTotal;
            const difference = actualCash - expectedCash;

            await updateDoc(doc(db, 'closures', currentSession.id), {
                totalSales: metrics.totalSales,
                orderCount: metrics.orderCount,
                salesByWaiter: metrics.salesByWaiter,
                salesByPaymentMethod: metrics.salesByPaymentMethod,
                expectedCash,
                actualCash,
                difference,
                status: 'closed',
                closedAt: getPeruNow()
            });
            alert(`✅ Caja Cerrada Correctamente\n\nDiferencia: S/ ${difference.toFixed(2)}`);
        } catch (error) {
            console.error('Error closing box:', error);
            alert('❌ Error al cerrar caja.');
        } finally {
            setIsClosing(false);
        }
    };



    // ── APERTURA DE CAJA ─────────────────────────────────────────────────────
    if (isToday && !sessionExists) {
        return (
            <div className="container mt-md" style={{ maxWidth: '480px' }}>
                <Button variant="ghost" onClick={() => navigate(-1)} style={{ display: 'inline-flex', alignItems: 'center', gap: '0.4rem', marginBottom: '1.5rem', fontSize: '0.9rem' }}>
                    <ArrowLeft size={16} /> Volver
                </Button>
                <Card style={{ padding: '2.5rem 2rem', textAlign: 'center' }}>
                    <div style={{
                        background: 'linear-gradient(135deg, rgba(37,99,235,0.12), rgba(37,99,235,0.06))',
                        width: '80px', height: '80px', borderRadius: '50%',
                        display: 'flex', alignItems: 'center', justifyContent: 'center',
                        margin: '0 auto 1.5rem', border: '2px solid rgba(37,99,235,0.15)'
                    }}>
                        <Wallet size={36} color="var(--primary-color)" />
                    </div>
                    <h1 style={{ fontSize: '1.5rem', fontWeight: '800', marginBottom: '0.5rem' }}>Apertura de Caja</h1>
                    <p style={{ color: 'var(--text-secondary)', marginBottom: '2rem', fontSize: '0.95rem' }}>
                        Para registrar ventas hoy <strong>({formatPeruDisplay(targetDate)})</strong>, abre la caja con el monto inicial en efectivo.
                    </p>
                    <div style={{ textAlign: 'left', marginBottom: '1.5rem' }}>
                        <Input
                            label="Monto Inicial (S/)"
                            type="number"
                            placeholder="0.00"
                            value={openingBalanceInput}
                            onChange={e => setOpeningBalanceInput(e.target.value)}
                        />
                        <p style={{ fontSize: '0.78rem', color: 'var(--text-secondary)', marginTop: '0.4rem' }}>
                            Puedes ingresar 0 si no tienes efectivo en caja.
                        </p>
                    </div>
                    <Button fullWidth onClick={() => openSession(parseFloat(openingBalanceInput) || 0)} style={{ fontWeight: '700', fontSize: '1rem' }}>
                        Abrir Caja Ahora
                    </Button>
                    <Button variant="ghost" fullWidth onClick={() => navigate(-1)} style={{ marginTop: '0.75rem' }}>
                        Cancelar
                    </Button>
                </Card>
            </div>
        );
    }

    // ── MAIN LAYOUT ──────────────────────────────────────────────────────────
    return (
        <div className="container mt-md">

            {/* ── RESPONSIVE HEADER ── */}
            <header style={{
                marginBottom: '1.5rem',
                paddingBottom: '1.25rem',
                borderBottom: '1px solid var(--divider-color)'
            }}>
                {/* Top row: back button + action buttons */}
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', gap: '0.5rem', flexWrap: 'wrap', marginBottom: '0.75rem' }}>
                    <Button variant="ghost" onClick={() => navigate(-1)} size="sm" style={{ display: 'inline-flex', alignItems: 'center', gap: '0.35rem', flexShrink: 0 }}>
                        <ArrowLeft size={16} /> Volver
                    </Button>

                    {/* Action buttons — icon-only on mobile, labeled on desktop */}
                    <div style={{ display: 'flex', gap: '0.5rem', flexShrink: 0 }}>

                        <button
                            onClick={() => exportDailySalesToExcel(metrics, orders, undefined, pettyCashExpenseItems.length > 0 ? pettyCashExpenseItems : undefined)}
                            disabled={metrics.orderCount === 0}
                            title="Exportar Excel"
                            style={{
                                display: 'flex', alignItems: 'center', gap: '0.4rem',
                                padding: '0.5rem 0.85rem', borderRadius: 'var(--radius-md)',
                                background: 'var(--surface-color)', color: 'var(--text-primary)',
                                border: '1px solid var(--border-color)', cursor: metrics.orderCount === 0 ? 'not-allowed' : 'pointer',
                                fontWeight: '700', fontSize: '0.82rem', opacity: metrics.orderCount === 0 ? 0.5 : 1,
                                whiteSpace: 'nowrap'
                            }}
                        >
                            <Download size={15} />
                            <span className="btn-label">Excel</span>
                        </button>
                    </div>
                </div>

                {/* Title block */}
                <div>
                    <h1 style={{ margin: 0, fontSize: 'clamp(1.3rem, 4vw, 1.8rem)', fontWeight: '900', lineHeight: 1.2 }}>
                        Cierre de Caja
                    </h1>
                    <p style={{ margin: '0.25rem 0 0', color: 'var(--text-secondary)', fontSize: '0.9rem' }}>
                        Resumen del día: <strong style={{ color: 'var(--text-primary)' }}>{formatPeruDisplay(targetDate)}</strong>
                    </p>
                </div>
            </header>

            {/* ── ALERTS ── */}
            {isClosed && (
                <div style={{
                    background: 'var(--surface-color)', color: 'var(--success-color)',
                    padding: '1rem 1.25rem', borderRadius: 'var(--radius-lg)',
                    marginBottom: '1.25rem', border: '1px solid var(--border-color)',
                    borderLeft: '5px solid var(--success-color)',
                    display: 'flex', alignItems: 'flex-start', gap: '0.75rem',
                    boxShadow: 'var(--shadow-sm)'
                }}>
                    <CheckCircle size={20} style={{ flexShrink: 0, marginTop: '2px' }} />
                    <span style={{ fontWeight: '600', fontSize: '0.9rem', lineHeight: '1.4' }}>
                        <strong style={{ textTransform: 'uppercase', marginRight: '0.4rem' }}>Caja Cerrada:</strong>
                        Arqueo finalizado para el {formatPeruDisplay(targetDate)}. Operaciones bloqueadas.
                    </span>
                </div>
            )}

            {hasPendingOrders && (
                <div style={{
                    background: 'var(--surface-color)', color: 'var(--danger-color)',
                    padding: '1rem 1.25rem', borderRadius: 'var(--radius-lg)',
                    marginBottom: '1.25rem', border: '1px solid var(--border-color)',
                    borderLeft: '5px solid var(--danger-color)',
                    display: 'flex', alignItems: 'flex-start', gap: '0.75rem',
                    boxShadow: 'var(--shadow-sm)'
                }}>
                    <AlertTriangle size={20} style={{ flexShrink: 0, marginTop: '2px' }} />
                    <span style={{ fontWeight: '600', fontSize: '0.9rem', lineHeight: '1.4' }}>
                        <strong style={{ textTransform: 'uppercase', marginRight: '0.4rem' }}>Imposible Cerrar:</strong>
                        Hay {activeOrders.length} pedido{activeOrders.length !== 1 ? 's' : ''} activo{activeOrders.length !== 1 ? 's' : ''}.
                        Debes cerrarlos antes del cierre.
                    </span>
                </div>
            )}

            {/* Petty Cash Pending Warning */}
            {pettyCashPendingCount > 0 && !isClosed && (
                <div style={{
                    background: 'rgba(245,158,11,0.08)', color: '#b45309',
                    padding: '1rem 1.25rem', borderRadius: 'var(--radius-lg)',
                    marginBottom: '1.25rem', border: '1px solid rgba(245,158,11,0.2)',
                    borderLeft: '5px solid #f59e0b',
                    display: 'flex', alignItems: 'center', justifyContent: 'space-between',
                    gap: '0.75rem', flexWrap: 'wrap',
                    boxShadow: 'var(--shadow-sm)'
                }}>
                    <div style={{ display: 'flex', alignItems: 'center', gap: '0.6rem' }}>
                        <Wallet size={20} color="#f59e0b" />
                        <span style={{ fontWeight: '600', fontSize: '0.88rem' }}>
                            <strong>{pettyCashPendingCount}</strong> gasto{pettyCashPendingCount !== 1 ? 's' : ''} de caja chica pendiente{pettyCashPendingCount !== 1 ? 's' : ''} de aprobación.
                        </span>
                    </div>
                    <button
                        onClick={() => navigate(`/${restaurantSlug}/caja-chica`)}
                        style={{
                            display: 'flex', alignItems: 'center', gap: '0.3rem',
                            padding: '0.4rem 0.85rem', borderRadius: 'var(--radius-md)',
                            background: '#f59e0b', color: 'white', border: 'none',
                            cursor: 'pointer', fontWeight: '700', fontSize: '0.8rem',
                        }}
                    >
                        Revisar <ExternalLink size={14} />
                    </button>
                </div>
            )}

            {/* Caja Chica Quick Access */}
            {isToday && sessionExists && !isClosed && (
                <div style={{
                    background: 'rgba(37,99,235,0.05)',
                    padding: '0.85rem 1.25rem', borderRadius: 'var(--radius-lg)',
                    marginBottom: '1.25rem', border: '1px solid rgba(37,99,235,0.12)',
                    display: 'flex', alignItems: 'center', justifyContent: 'space-between',
                    gap: '0.75rem', flexWrap: 'wrap',
                }}>
                    <div style={{ display: 'flex', alignItems: 'center', gap: '0.6rem' }}>
                        <Wallet size={18} color="var(--primary-color)" />
                        <span style={{ fontWeight: '600', fontSize: '0.85rem', color: 'var(--text-primary)' }}>
                            Caja Chica: <strong style={{ color: 'var(--danger-color)' }}>S/ {pettyCashApprovedTotal.toFixed(2)}</strong> en gastos aprobados hoy
                        </span>
                    </div>
                    <button
                        onClick={() => navigate(`/${restaurantSlug}/caja-chica`)}
                        style={{
                            display: 'flex', alignItems: 'center', gap: '0.3rem',
                            padding: '0.4rem 0.85rem', borderRadius: 'var(--radius-md)',
                            background: 'var(--primary-color)', color: 'white', border: 'none',
                            cursor: 'pointer', fontWeight: '700', fontSize: '0.8rem',
                        }}
                    >
                        Ir a Caja Chica <ExternalLink size={14} />
                    </button>
                </div>
            )}

            {/* ── METRICS GRID ── */}
            <div style={{
                display: 'grid',
                gridTemplateColumns: 'repeat(auto-fit, minmax(min(100%, 280px), 1fr))',
                gap: '1rem',
                marginBottom: '2rem'
            }}>
                {/* Total Recaudado */}
                <Card style={{ padding: '1.5rem', borderTop: '4px solid var(--primary-color)', boxShadow: 'var(--shadow-md)', borderRadius: 'var(--radius-xl)' }}>
                    <div style={{ display: 'flex', alignItems: 'center', gap: '0.6rem', marginBottom: '0.75rem' }}>
                        <div style={{ width: '36px', height: '36px', borderRadius: 'var(--radius-md)', background: 'rgba(37,99,235,0.1)', display: 'flex', alignItems: 'center', justifyContent: 'center', flexShrink: 0 }}>
                            <DollarSign size={20} style={{ color: 'var(--primary-color)' }} />
                        </div>
                        <h3 style={{ margin: 0, fontWeight: '800', color: 'var(--text-secondary)', textTransform: 'uppercase', letterSpacing: '0.05em', fontSize: '0.8rem' }}>Total Recaudado</h3>
                    </div>
                    <div style={{ fontSize: 'clamp(2.2rem, 8vw, 3.2rem)', fontWeight: '900', color: 'var(--text-primary)', letterSpacing: '-0.03em', lineHeight: '1.1', marginBottom: '1rem' }}>
                        S/ {metrics.totalSales.toFixed(2)}
                    </div>
                    <div style={{ display: 'flex', flexDirection: 'column', gap: '0.4rem', borderTop: '1px solid var(--divider-color)', paddingTop: '0.75rem' }}>
                        <div style={{ display: 'flex', justifyContent: 'space-between', color: 'var(--text-secondary)', fontSize: '0.88rem' }}>
                            <span>Monto Inicial</span>
                            <strong style={{ color: 'var(--text-primary)' }}>S/ {currentSession?.openingBalance?.toFixed(2) || '0.00'}</strong>
                        </div>
                        <div style={{ display: 'flex', justifyContent: 'space-between', color: 'var(--success-color)', fontSize: '0.88rem' }}>
                            <span>Ventas (Solo Efectivo)</span>
                            <strong>+ S/ {Object.entries(metrics.salesByPaymentMethod).filter(([m]) => ['cash', 'efectivo'].includes(m.toLowerCase())).reduce((s, [_, a]) => s + a, 0).toFixed(2)}</strong>
                        </div>
                        <div style={{ display: 'flex', justifyContent: 'space-between', color: 'var(--danger-color)', fontSize: '0.88rem' }}>
                            <span>Gastos Caja Chica</span>
                            <strong>- S/ {pettyCashApprovedTotal.toFixed(2)}</strong>
                        </div>
                        <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: '0.88rem', marginTop: '0.25rem', paddingTop: '0.4rem', borderTop: '1px dashed var(--divider-color)' }}>
                            <span style={{ color: 'var(--text-secondary)' }}>Pedidos</span>
                            <strong style={{ color: 'var(--text-primary)' }}>{metrics.orderCount}</strong>
                        </div>
                    </div>
                </Card>

                {/* Medios de Pago */}
                <Card style={{ padding: '1.5rem', borderRadius: 'var(--radius-xl)', boxShadow: 'var(--shadow-md)' }}>
                    <div style={{ display: 'flex', alignItems: 'center', gap: '0.6rem', marginBottom: '1rem', borderBottom: '1px solid var(--divider-color)', paddingBottom: '0.75rem' }}>
                        <div style={{ width: '36px', height: '36px', borderRadius: 'var(--radius-md)', background: 'rgba(37,99,235,0.1)', display: 'flex', alignItems: 'center', justifyContent: 'center', flexShrink: 0 }}>
                            <CreditCard size={18} style={{ color: 'var(--primary-color)' }} />
                        </div>
                        <h3 style={{ margin: 0, fontWeight: '800', fontSize: '0.9rem', color: 'var(--text-primary)' }}>Medios de Pago</h3>
                    </div>
                    <div style={{ display: 'flex', flexDirection: 'column', gap: '0.6rem' }}>
                        {Object.entries(metrics.salesByPaymentMethod).length === 0
                            ? <p style={{ color: 'var(--text-secondary)', fontStyle: 'italic', fontSize: '0.88rem', margin: 0 }}>Sin movimientos</p>
                            : Object.entries(metrics.salesByPaymentMethod).map(([method, amount]) => (
                                <div key={method} style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', borderBottom: '1px solid var(--divider-color)', paddingBottom: '0.5rem' }}>
                                    <Badge variant="neutral" style={{ textTransform: 'capitalize', fontWeight: '700', fontSize: '0.75rem' }}>{method}</Badge>
                                    <span style={{ fontWeight: '800', color: 'var(--text-primary)', fontSize: '0.95rem' }}>S/ {amount.toFixed(2)}</span>
                                </div>
                            ))
                        }
                    </div>
                </Card>

                {/* Rendimiento Mozos */}
                <Card style={{ padding: '1.5rem', borderRadius: 'var(--radius-xl)', boxShadow: 'var(--shadow-md)' }}>
                    <div style={{ display: 'flex', alignItems: 'center', gap: '0.6rem', marginBottom: '1rem', borderBottom: '1px solid var(--divider-color)', paddingBottom: '0.75rem' }}>
                        <div style={{ width: '36px', height: '36px', borderRadius: 'var(--radius-md)', background: 'rgba(37,99,235,0.1)', display: 'flex', alignItems: 'center', justifyContent: 'center', flexShrink: 0 }}>
                            <User size={18} style={{ color: 'var(--primary-color)' }} />
                        </div>
                        <h3 style={{ margin: 0, fontWeight: '800', fontSize: '0.9rem', color: 'var(--text-primary)' }}>Rendimiento Mozos</h3>
                    </div>
                    <div style={{ display: 'flex', flexDirection: 'column', gap: '0.6rem' }}>
                        {Object.entries(metrics.salesByWaiter).length === 0
                            ? <p style={{ color: 'var(--text-secondary)', fontStyle: 'italic', fontSize: '0.88rem', margin: 0 }}>Sin movimientos</p>
                            : Object.entries(metrics.salesByWaiter).map(([waiter, amount]) => (
                                <div key={waiter} style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', borderBottom: '1px solid var(--divider-color)', paddingBottom: '0.5rem' }}>
                                    <span style={{ fontWeight: '600', color: 'var(--text-primary)', fontSize: '0.9rem' }}>{waiter}</span>
                                    <strong style={{ color: 'var(--primary-color)', fontWeight: '800', fontSize: '0.95rem' }}>S/ {amount.toFixed(2)}</strong>
                                </div>
                            ))
                        }
                    </div>
                </Card>
            </div>

            {/* ── CIERRE SECTION ── */}
            <Card style={{ padding: 'clamp(1.5rem, 5vw, 2.5rem)', borderRadius: 'var(--radius-xl)', boxShadow: 'var(--shadow-lg)' }}>
                {!isClosed ? (
                    <div style={{ maxWidth: '520px', margin: '0 auto' }}>
                        <h3 style={{ display: 'flex', alignItems: 'center', gap: '0.5rem', marginBottom: '1.5rem', fontSize: '1rem', fontWeight: '800' }}>
                            <List size={20} style={{ color: 'var(--primary-color)' }} /> Arqueo de Efectivo
                        </h3>

                        <div style={{ background: 'var(--background-color)', padding: '1.25rem', borderRadius: 'var(--radius-md)', border: '1px solid var(--divider-color)', marginBottom: '1.5rem' }}>
                            <Input
                                label="Efectivo Físico en Caja (S/)"
                                type="number"
                                placeholder="Cuenta el dinero físico..."
                                value={actualCashInput}
                                onChange={e => setActualCashInput(e.target.value)}
                            />
                            <p style={{ fontSize: '0.78rem', color: 'var(--text-secondary)', marginTop: '0.4rem' }}>
                                Ingresa el total en efectivo para calcular diferencias.
                            </p>
                        </div>

                        <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'center', gap: '0.5rem', marginBottom: '1.25rem', color: 'var(--text-secondary)', fontSize: '0.85rem', fontWeight: '600' }}>
                            <AlertTriangle size={16} style={{ color: 'var(--danger-color)', flexShrink: 0 }} />
                            Al cerrar caja se bloquearán las ventas del día.
                        </div>

                        <Button
                            variant="primary"
                            onClick={handleCloseBox}
                            disabled={isClosing || !canClose}
                            fullWidth
                            style={{
                                fontSize: 'clamp(0.95rem, 3vw, 1.1rem)',
                                padding: '1rem',
                                opacity: !canClose ? 0.4 : 1,
                                cursor: !canClose ? 'not-allowed' : 'pointer',
                                backgroundColor: 'var(--danger-color)',
                                border: 'none',
                                borderRadius: 'var(--radius-md)',
                                fontWeight: '800',
                                boxShadow: canClose ? '0 6px 16px rgba(230, 57, 70, 0.25)' : 'none',
                                display: 'flex', alignItems: 'center', justifyContent: 'center', gap: '0.5rem'
                            }}
                        >
                            {isClosing ? 'PROCESANDO...' : <><Lock size={18} /> CERRAR CAJA Y TERMINAR DÍA</>}
                        </Button>
                    </div>
                ) : (
                    <div style={{ textAlign: 'center' }}>
                        <div style={{ marginBottom: '1.5rem' }}>
                            <Badge variant="success" style={{ padding: '0.75rem 1.5rem', fontSize: '1rem', display: 'inline-flex', alignItems: 'center', gap: '0.5rem' }}>
                                <Check size={18} /> CAJA CERRADA EXITOSAMENTE
                            </Badge>
                        </div>
                        <div style={{
                            display: 'grid',
                            gridTemplateColumns: 'repeat(auto-fit, minmax(120px, 1fr))',
                            gap: '1rem',
                            maxWidth: '480px', margin: '0 auto'
                        }}>
                            {[
                                { label: 'Efectivo (Sistema)', value: `S/ ${currentSession?.expectedCash?.toFixed(2) ?? '—'}` },
                                { label: 'Efectivo Físico', value: `S/ ${currentSession?.actualCash?.toFixed(2) ?? '—'}` },
                                {
                                    label: 'Diferencia',
                                    value: `S/ ${currentSession?.difference?.toFixed(2) ?? '—'}`,
                                    color: (currentSession?.difference || 0) < 0 ? 'var(--danger-color)' : 'var(--success-color)'
                                }
                            ].map(({ label, value, color }) => (
                                <div key={label} style={{ background: 'var(--background-color)', padding: '1rem', borderRadius: 'var(--radius-md)', border: '1px solid var(--divider-color)' }}>
                                    <p style={{ fontSize: '0.75rem', color: 'var(--text-secondary)', textTransform: 'uppercase', fontWeight: '700', margin: '0 0 0.4rem', letterSpacing: '0.04em' }}>{label}</p>
                                    <p style={{ fontSize: '1.3rem', fontWeight: '900', margin: 0, color: color || 'var(--text-primary)' }}>{value}</p>
                                </div>
                            ))}
                        </div>
                    </div>
                )}
            </Card>



            {/* Inline CSS for responsive label hiding */}
            <style>{`
                @media (max-width: 480px) {
                    .btn-label { display: none; }
                }
                @keyframes spin {
                    to { transform: rotate(360deg); }
                }
            `}</style>
        </div>
    );
}

import { useRef, useEffect, useState } from 'react';
import { Lock, ShieldCheck, ChefHat, LogOut, Menu, Wallet, Zap, DollarSign } from 'lucide-react';
import type { RestaurantTable, Order } from '@/types';
import { OrderModal } from '@/components/features/OrderModal';
import { TableDetailModal } from '@/components/features/TableDetailModal';
import { TableSelectorModal } from '@/components/features/TableSelectorModal';
import { useNavigate, useParams } from 'react-router-dom';
import { useAuth } from '@/hooks/useAuth';
import { useOrders } from '@/hooks/useOrders';
import { useClosureStatus } from '@/hooks/useClosureStatus';
import { useOrderCreation } from '@/hooks/useOrderCreation';
import { OrderFAB } from '@/components/shared/OrderFAB';
import { OrderCard } from '@/components/features/OrderCard';
import { OrderCardSkeleton } from '@/components/shared/Skeleton';
import { NotificationBell } from '@/components/shared/NotificationBell';
import { useTenant } from '@/app/providers/TenantProvider';
import { OrderStatus } from '@/types';

export function CocinaPage() {
    const { user, logout } = useAuth();
    const navigate = useNavigate();
    const { restaurantSlug } = useParams<{ restaurantSlug: string }>();
    const { activeOrders, deleteOrder } = useOrders();
    const { isClosed } = useClosureStatus();
    const [filterStatus, setFilterStatus] = useState<OrderStatus | 'all'>('all');
    const [isMenuOpen, setIsMenuOpen] = useState(false);
    const menuRef = useRef<HTMLDivElement>(null);
    const { tenant } = useTenant();
    const enableQuickSale = tenant?.config?.enableQuickSale ?? false;

    // Close menu when clicking outside
    useEffect(() => {
        function handleClickOutside(event: MouseEvent) {
            if (menuRef.current && !menuRef.current.contains(event.target as Node)) {
                setIsMenuOpen(false);
            }
        }
        document.addEventListener("mousedown", handleClickOutside);
        return () => document.removeEventListener("mousedown", handleClickOutside);
    }, []);

    // Order creation flow (reusable hook)
    const orderCreation = useOrderCreation();
    const [orderToEdit, setOrderToEdit] = useState<Order | undefined>(undefined);

    if (!activeOrders) {
        return (
            <div style={{ minHeight: '100vh', backgroundColor: 'var(--background-color)' }}>
                <div style={{ height: '90px', backgroundColor: 'var(--surface-color)', borderBottom: '1px solid var(--border-color)', marginBottom: '2.5rem' }} />
                <div className="container" style={{
                    display: 'grid',
                    gridTemplateColumns: 'repeat(auto-fill, minmax(360px, 1fr))',
                    gap: '1.5rem'
                }}>
                    {[1, 2, 3, 4, 5, 6].map(i => (
                        <OrderCardSkeleton key={i} />
                    ))}
                </div>
            </div>
        );
    }

    const filteredOrders = activeOrders.filter(order =>
        filterStatus === 'all' ? true : order.status === filterStatus
    );

    const getCount = (status: OrderStatus) => activeOrders.filter(o => o.status === status).length;

    const handleDelete = async (orderId: string) => {
        if (confirm('¿Estás seguro de eliminar este pedido? Esta acción liberará la mesa.')) {
            await deleteOrder(orderId);
        }
    };

    // Helper to construct minimal table object for OrderModal
    const getMinimalTable = (order: Order): RestaurantTable => ({
        id: 'temp', // Not used for update
        restaurantId: user?.restaurantId || '',
        number: order.tableNumber,
        status: 'occupied',
        capacity: 4 // Dummy
    });

    const FilterButton = ({ status, label }: { status: OrderStatus | 'all', label: string }) => {
        const isActive = filterStatus === status;
        const count = status === 'all' ? activeOrders.length : getCount(status as OrderStatus);

        return (
            <button
                onClick={() => setFilterStatus(status)}
                style={{
                    backgroundColor: isActive ? 'var(--primary-color)' : 'var(--surface-color)',
                    color: isActive ? 'white' : 'var(--text-secondary)',
                    border: '1px solid',
                    borderColor: isActive ? 'var(--primary-color)' : 'var(--border-color)',
                    padding: '0.65rem 1.25rem',
                    borderRadius: 'var(--radius-full)',
                    cursor: 'pointer',
                    fontWeight: '700',
                    display: 'flex',
                    alignItems: 'center',
                    gap: '0.75rem',
                    transition: 'all 0.2s',
                    boxShadow: isActive ? 'var(--shadow-md)' : 'var(--shadow-sm)',
                    fontSize: '0.9rem',
                    flexShrink: 0
                }}
            >
                {label}
                {count > 0 && (
                    <span style={{
                        backgroundColor: isActive ? 'rgba(255,255,255,0.2)' : 'var(--divider-color)',
                        color: isActive ? 'white' : 'var(--text-primary)',
                        padding: '2px 8px',
                        borderRadius: 'var(--radius-full)',
                        fontSize: '0.75rem',
                        minWidth: '22px',
                        textAlign: 'center',
                        fontWeight: '800'
                    }}>
                        {count}
                    </span>
                )}
            </button>
        );
    };

    return (
        <div style={{ minHeight: '100vh', backgroundColor: 'var(--background-color)', paddingBottom: '3rem' }}>
            {/* Header */}
            <style>{`
                .cocina-layout-header {
                    display: flex;
                    flex-direction: column;
                }
                .cocina-layout-top {
                    display: flex;
                    justify-content: space-between;
                    align-items: center;
                    margin-bottom: 1rem;
                }
                .cocina-layout-actions {
                    display: flex;
                    gap: 0.75rem;
                }
                .cocina-action-btn {
                    flex: 1;
                    justify-content: center;
                    border: none !important;
                    border-radius: 14px !important;
                    transition: transform 0.15s, opacity 0.15s;
                }
                .cocina-action-btn:active {
                    transform: scale(0.97);
                }
                .cocina-dropdown-menu {
                    position: absolute;
                    top: 100%;
                    right: 0;
                    margin-top: 0.5rem;
                    background: var(--surface-color);
                    border: 1px solid var(--border-color);
                    border-radius: 12px;
                    box-shadow: 0 10px 25px rgba(0,0,0,0.1);
                    min-width: 200px;
                    z-index: 50;
                    opacity: 0;
                    transform: translateY(-10px);
                    pointer-events: none;
                    transition: all 0.2s cubic-bezier(0.16, 1, 0.3, 1);
                    display: flex;
                    flex-direction: column;
                    padding: 0.5rem;
                    gap: 0.25rem;
                }
                .cocina-dropdown-menu.open {
                    opacity: 1;
                    transform: translateY(0);
                    pointer-events: auto;
                }
                .cocina-dropdown-item {
                    display: flex;
                    align-items: center;
                    gap: 0.75rem;
                    padding: 0.75rem 1rem;
                    border: none;
                    background: transparent;
                    width: 100%;
                    text-align: left;
                    border-radius: 8px;
                    cursor: pointer;
                    font-size: 0.95rem;
                    font-weight: 600;
                    transition: background 0.15s;
                }
                .cocina-dropdown-item:hover {
                    background: var(--background-color);
                }
                .cocina-dropdown-item.danger {
                    color: var(--danger-color);
                }
                .cocina-dropdown-item.danger:hover {
                    background: rgba(230, 57, 70, 0.08);
                }
                @media (min-width: 768px) {
                    .cocina-layout-header {
                        flex-direction: row;
                        justify-content: space-between;
                        align-items: center;
                    }
                    .cocina-layout-top {
                        margin-bottom: 0;
                        flex: 1;
                    }
                }
            `}</style>
            <div style={{ backgroundColor: 'var(--surface-color)', borderBottom: '1px solid var(--border-color)', padding: '1.25rem 0', marginBottom: '2.5rem', boxShadow: 'var(--shadow-sm)', position: 'relative', zIndex: 100 }}>
                <div className="container cocina-layout-header">
                    <div className="cocina-layout-top">
                        <div style={{ display: 'flex', alignItems: 'center', gap: '0.85rem', flex: 1, minWidth: 0 }}>
                            <div style={{
                                width: '46px', height: '46px',
                                backgroundColor: 'rgba(237, 219, 203, 0.4)',
                                borderRadius: '50%',
                                display: 'flex', alignItems: 'center', justifyContent: 'center',
                                color: 'var(--text-primary)',
                                flexShrink: 0
                            }}>
                                <ChefHat size={24} />
                            </div>
                            <div style={{ minWidth: 0 }}>
                                <h1 style={{ margin: 0, color: 'var(--text-primary)', fontSize: '1.25rem', fontWeight: '800', letterSpacing: '-0.01em', whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>
                                    {user?.role === 'caja' ? 'Caja' : 'Cocina'}
                                </h1>
                                <p style={{ margin: 0, color: 'var(--text-secondary)', fontSize: '0.85rem', fontWeight: '500', whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>
                                    Hola, <span style={{ color: 'var(--primary-color)' }}>{user?.name}</span> &bull; {filteredOrders.length} pedidos
                                </p>
                            </div>
                        </div>

                        <div style={{ flexShrink: 0, paddingLeft: '0.5rem', display: 'flex', alignItems: 'center', gap: '0.75rem' }}>
                            <NotificationBell />
                            <div ref={menuRef} style={{ position: 'relative' }}>
                                <button
                                    onClick={() => setIsMenuOpen(!isMenuOpen)}
                                    style={{
                                        display: 'flex', alignItems: 'center', justifyContent: 'center',
                                        width: '42px', height: '42px',
                                        borderRadius: '50%',
                                        border: '1px solid var(--border-color)',
                                        background: isMenuOpen ? 'var(--background-color)' : 'transparent',
                                        color: 'var(--text-primary)',
                                        cursor: 'pointer',
                                        transition: 'all 0.2s',
                                    }}
                                >
                                    <Menu size={20} />
                                </button>

                                <div className={`cocina-dropdown-menu ${isMenuOpen ? 'open' : ''}`}>
                                    {user?.role === 'admin' && (
                                        <button
                                            className="cocina-dropdown-item"
                                            onClick={() => navigate(`/${restaurantSlug}/admin`)}
                                        >
                                            <ShieldCheck size={18} style={{ color: 'var(--primary-color)' }} />
                                            <span>Administración</span>
                                        </button>
                                    )}
                                    <button
                                        className="cocina-dropdown-item"
                                        onClick={() => { navigate(`/${restaurantSlug}/caja-chica`); setIsMenuOpen(false); }}
                                    >
                                        <Wallet size={18} style={{ color: '#f59e0b' }} />
                                        <span>Caja Chica</span>
                                    </button>
                                    {(user?.role === 'admin' || user?.role === 'caja') && (
                                        <button
                                            className="cocina-dropdown-item"
                                            onClick={() => { navigate(`/${restaurantSlug}/cierre-caja`); setIsMenuOpen(false); }}
                                        >
                                            <DollarSign size={18} className="text-primary" />
                                            <span>Cerrar Caja</span>
                                        </button>
                                    )}
                                    <button
                                        className="cocina-dropdown-item danger"
                                        onClick={logout}
                                    >
                                        <LogOut size={18} />
                                        <span>Cerrar Sesión</span>
                                    </button>
                                </div>
                            </div>
                        </div>
                    </div>
                </div>
            </div>

            <div className="container">
                {/* Closure Banner */}
                {isClosed && (
                    <div style={{
                        background: 'var(--surface-color)',
                        color: 'var(--danger-color)',
                        padding: '1.25rem 2rem',
                        borderRadius: 'var(--radius-lg)',
                        marginBottom: '2.5rem',
                        border: '1px solid var(--border-color)',
                        borderLeft: '5px solid var(--danger-color)',
                        display: 'flex', alignItems: 'center', gap: '1.25rem',
                        boxShadow: 'var(--shadow-md)'
                    }}>
                        <Lock size={22} />
                        <div>
                            <strong style={{ display: 'block', fontSize: '1.1rem', fontWeight: '800', textTransform: 'uppercase', letterSpacing: '0.05em' }}>Servicio Finalizado</strong>
                            <span style={{ fontSize: '0.9rem', color: 'var(--text-secondary)', fontWeight: '600' }}>Se ha realizado el cierre de caja. Solo lectura.</span>
                        </div>
                    </div>
                )}

                {/* Filters */}
                <div style={{
                    display: 'flex',
                    alignItems: 'center',
                    gap: '1.5rem',
                    marginBottom: '2rem',
                    flexWrap: 'nowrap',
                    overflowX: 'hidden'
                }}>
                    <div style={{
                        display: 'flex',
                        gap: '0.85rem',
                        flexWrap: 'nowrap',
                        overflowX: 'auto',
                        paddingBottom: '8px',
                        msOverflowStyle: 'none',
                        scrollbarWidth: 'none',
                        WebkitOverflowScrolling: 'touch'
                    }}>
                        <style>{`
                            div::-webkit-scrollbar {
                                display: none;
                            }
                        `}</style>
                        <FilterButton status="all" label="Todos" />
                        <FilterButton status="pending" label="Pendientes" />
                        <FilterButton status="in_preparation" label="En Cocina" />
                        <FilterButton status="ready" label="Listos" />
                    </div>
                </div>

                {/* Grid */}
                <div style={{
                    display: 'grid',
                    gridTemplateColumns: 'repeat(auto-fill, minmax(360px, 1fr))',
                    gap: '1.5rem'
                }}>
                    {filteredOrders.map(order => (
                        <OrderCard
                            key={order.id}
                            order={order}
                            onEdit={() => setOrderToEdit(order)}
                            onDelete={() => handleDelete(order.id)}
                        />
                    ))}

                    {activeOrders.length === 0 && (
                        <div style={{ gridColumn: '1/-1', textAlign: 'center', padding: '6rem 2rem', color: 'var(--text-secondary)', background: 'var(--surface-color)', borderRadius: 'var(--radius-lg)', border: '1px solid var(--border-color)', borderStyle: 'dashed' }}>
                            <div style={{ fontSize: '4.5rem', marginBottom: '1.5rem', opacity: 0.15 }}>⚡</div>
                            <h3 style={{ color: 'var(--text-primary)', marginBottom: '0.5rem', fontWeight: '800', fontSize: '1.25rem' }}>No hay pedidos en curso</h3>
                            <p style={{ fontWeight: '500' }}>Los pedidos que generen los mozos aparecerán aquí al instante.</p>
                        </div>
                    )}
                </div>
            </div>
            {orderToEdit && user?.restaurantId && (
                <OrderModal
                    table={getMinimalTable(orderToEdit)}
                    initialOrder={orderToEdit}
                    onClose={() => setOrderToEdit(undefined)}
                    onOrderCreated={() => { /* Order saved, let modal handle closure */ }}
                />
            )}

            {/* --- Order Creation Flow (FAB + Modals) --- */}
            {user?.role === 'caja' ? (
                // Left side layout for the Plus FAB when there's a quick sale button, or regular if admin
                <div style={{ position: 'fixed', bottom: '2rem', right: '2rem', display: 'flex', gap: '1rem', zIndex: 900 }}>
                    <div style={{ position: 'relative' }}>
                        <OrderFAB onClick={orderCreation.handleFABClick} style={{ position: 'relative', bottom: 0, right: 0 }} />
                    </div>
                    {enableQuickSale && (
                        <button
                            onClick={() => {
                                if (orderCreation.isClosed) {
                                    alert('⚠️ Caja Cerrada\n\nNo se pueden crear nuevos pedidos hoy.');
                                    return;
                                }
                                orderCreation.setTakeoutOrderType('quick-sale');
                                orderCreation.setIsOrderModalOpen(true);
                            }}
                            style={{
                                width: '64px',
                                height: '64px',
                                borderRadius: '50%',
                                border: 'none',
                                background: 'linear-gradient(135deg, var(--primary-color) 0%, #6d4c41 100%)',
                                color: 'white',
                                display: 'flex',
                                alignItems: 'center',
                                justifyContent: 'center',
                                cursor: 'pointer',
                                boxShadow: '0 6px 20px rgba(142, 115, 91, 0.4), 0 2px 6px rgba(0,0,0,0.15)',
                                transition: 'all 0.3s cubic-bezier(0.4, 0, 0.2, 1)',
                                animation: 'fab-pulse 2s ease-in-out infinite',
                            }}
                            onMouseEnter={e => {
                                e.currentTarget.style.transform = 'scale(1.1)';
                                e.currentTarget.style.boxShadow = '0 8px 28px rgba(142, 115, 91, 0.5), 0 4px 10px rgba(0,0,0,0.2)';
                            }}
                            onMouseLeave={e => {
                                e.currentTarget.style.transform = 'scale(1)';
                                e.currentTarget.style.boxShadow = '0 6px 20px rgba(142, 115, 91, 0.4), 0 2px 6px rgba(0,0,0,0.15)';
                            }}
                            title="Venta Rápida"
                        >
                            <Zap size={28} fill="white" />
                        </button>
                    )}
                </div>
            ) : (
                <OrderFAB onClick={orderCreation.handleFABClick} />
            )}

            {orderCreation.showTableSelector && (
                <TableSelectorModal
                    tables={orderCreation.allTables}
                    activeOrders={orderCreation.activeOrders}
                    onTableClick={orderCreation.handleTableClick}
                    onClose={orderCreation.handleCloseTableSelector}
                />
            )}

            {orderCreation.isOrderModalOpen && (orderCreation.selectedTable || orderCreation.takeoutOrderType === 'takeout') && !orderCreation.isClosed && (
                <OrderModal
                    table={orderCreation.selectedTable || undefined}
                    initialOrder={orderCreation.orderToEdit}
                    onClose={orderCreation.handleCloseOrderModal}
                    onOrderCreated={() => { /* handled */ }}
                    orderType={orderCreation.takeoutOrderType}
                />
            )}

            {orderCreation.isDetailModalOpen && orderCreation.selectedTable && (
                <TableDetailModal
                    table={orderCreation.selectedTable}
                    onClose={orderCreation.handleCloseDetailModal}
                    onEdit={orderCreation.handleEditOrder}
                />
            )}
        </div>
    );
}

import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { doc, getDoc } from 'firebase/firestore';
import { db } from '@/services/firebase/config';
import { createRestaurant } from '@/services/onboardingService';
import { Card, Button, Input } from '@/components/shared';
import { AlertCircle } from 'lucide-react';

export function AuthForms() {
    const navigate = useNavigate();
    const [mode, setMode] = useState<'login' | 'register'>('login');

    // Login State
    const [slug, setSlug] = useState('');
    const [loginLoading, setLoginLoading] = useState(false);
    const [loginError, setLoginError] = useState<string | null>(null);

    // Register State
    const [regData, setRegData] = useState({
        name: '',
        slug: '',
        adminName: '',
        adminPin: ''
    });
    const [isLoading, setIsLoading] = useState(false);
